package com.chatwidgets;

import net.runelite.client.plugins.chatfilter.ChatFilterConfig;
import net.runelite.client.util.Text;
import org.apache.commons.lang3.StringUtils;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Matches widget messages against RuneLite's built-in Chat Filter plugin's word/regex lists,
 * mirroring {@code ChatFilterPlugin.updateFilteredPatterns()} and the normalization in
 * {@code censorMessage(username, message)}. Only the Filtered-words and Filtered-regex lists (plus
 * stripAccents) are used; name-based filtering and per-type gating flags are not ported. A match
 * means the message should be removed from the widgets entirely.
 *
 * <p>Patterns are (re)compiled via {@link #rebuild(ChatFilterConfig)} whenever the Chat Filter
 * config changes; {@link #matches(String)} runs per captured message.
 */
public class ChatMessageFilter {

    private List<Pattern> patterns = new ArrayList<>();
    private boolean stripAccents = false;

    /** Rebuilds the compiled pattern list from the Chat Filter plugin's live config. */
    public void rebuild(ChatFilterConfig cfg) {
        List<Pattern> compiled = new ArrayList<>();
        this.stripAccents = cfg.stripAccents();

        Text.fromCSV(cfg.filteredWords()).stream()
                .map(this::maybeStripAccents)
                .map(s -> Pattern.compile(Pattern.quote(s), Pattern.CASE_INSENSITIVE))
                .forEach(compiled::add);

        for (String line : cfg.filteredRegex().split("\n")) {
            String trimmed = maybeStripAccents(line.trim());
            if (trimmed.isEmpty()) {
                continue;
            }
            Pattern p = compilePattern(trimmed);
            if (p != null) {
                compiled.add(p);
            }
        }

        this.patterns = compiled;
    }

    /** Returns true when the message matches any filtered word/regex (i.e. should be removed). */
    public boolean matches(String message) {
        if (message == null || patterns.isEmpty()) {
            return false;
        }

        // Normalize like ChatFilterPlugin: non-breaking space (U+00A0) -> regular space.
        String normalized = maybeStripAccents(message
                .replace('\u00A0', ' ')
                .replace("<lt>", "<")
                .replace("<gt>", ">")
                .replace("<at>", "@"));

        for (Pattern pattern : patterns) {
            if (pattern.matcher(normalized).find()) {
                return true;
            }
        }
        return false;
    }

    private String maybeStripAccents(String input) {
        return stripAccents ? StringUtils.stripAccents(input) : input;
    }

    private static Pattern compilePattern(String pattern) {
        try {
            return Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
        } catch (PatternSyntaxException ex) {
            return null;
        }
    }
}

package com.chatwidgets;

import com.chatwidgets.model.MessageVariant;
import net.runelite.api.ChatMessageType;

import java.util.function.IntFunction;

/**
 * Mirrors how the chatbox cs2 ({@code rebuildchatbox}) splits certain message types at {@code |}
 * and hides one side, so hidden payloads ({@code CA_ID:565|}, GIM/PvP Arena prefixes, broadcast
 * link keys) never render raw in a widget. Pure: client lookups are passed in by the caller.
 *
 * <p>Per type:
 * <ul>
 *   <li>{@code GAMEMESSAGE}, {@code CLAN_MESSAGE}: split at the first {@code |}, show the right side;
 *       a {@code CA_ID:n} left side yields the achievement task id. {@code CLAN_MESSAGE} also
 *       recognises the GIM ({@code |text}) and PvP Arena ({@code p|text}) forms.</li>
 *   <li>{@code CLAN_GIM_MESSAGE}: GIM form, strip a leading {@code |} then split again.</li>
 *   <li>{@code CLAN_GIM_CHAT}, and {@code CLAN_CHAT} while in a GIM: strip a leading {@code |}.</li>
 *   <li>{@code BROADCAST}: reversed, keeps the left side; the right side's first char is a base-36
 *       key into {@code enum_63}, and a resolved URL prefixes the text with {@code <img=12> }.</li>
 *   <li>Everything else is untouched.</li>
 * </ul>
 *
 * <p>RuneLite retypes a {@code CLAN_MESSAGE} / {@code CLAN_CHAT} starting with {@code |} to its GIM
 * type and strips that {@code |} from the event message, but the {@link net.runelite.api.MessageNode}
 * value keeps it. Use {@link #parseEvent} for event/command text and {@link #parse} for node text;
 * guessing from the first character would discard a literal pipe in an event body. The {@code |} forms
 * under {@code CLAN_MESSAGE} / {@code CLAN_CHAT} are defensive, in case that retyping changes.
 */
public final class ChatPipeParser {

    private static final String CA_ID_PREFIX = "CA_ID:";
    private static final String BROADCAST_KEYS = "0123456789abcdefghijklmnopqrstuvwxyz";
    private static final String BROADCAST_ICON = "<img=12> ";

    private ChatPipeParser() {
    }

    /** Display text plus the payload recovered from the hidden side of the split. */
    public static final class Result {
        private final String text;
        private final MessageVariant variant;
        private final Integer achievementTaskId;
        private final String broadcastUrl;

        Result(String text, MessageVariant variant, Integer achievementTaskId, String broadcastUrl) {
            this.text = text;
            this.variant = variant;
            this.achievementTaskId = achievementTaskId;
            this.broadcastUrl = broadcastUrl;
        }

        static Result of(String text, MessageVariant variant) {
            return new Result(text, variant, null, null);
        }

        public String getText() {
            return text;
        }

        public MessageVariant getVariant() {
            return variant;
        }

        public Integer getAchievementTaskId() {
            return achievementTaskId;
        }

        public String getBroadcastUrl() {
            return broadcastUrl;
        }
    }

    /**
     * @param type               the message's chat type
     * @param raw                the raw node text (already trimmed)
     * @param inGim              whether the player is in a Group Ironman clan (gates clan chat)
     * @param broadcastUrlLookup {@code enum_63} lookup: base-36 key to URL, {@code null}/empty if unset
     */
    public static Result parse(ChatMessageType type, String raw, boolean inGim,
            IntFunction<String> broadcastUrlLookup) {
        switch (type) {
            case GAMEMESSAGE:
                return splitShowRight(raw, MessageVariant.NORMAL);
            case CLAN_MESSAGE:
                if (raw.startsWith("p|")) {
                    return Result.of(raw.substring(2), MessageVariant.PVP_ARENA);
                }
                if (raw.startsWith("|")) {
                    return gimNotification(raw);
                }
                return splitShowRight(raw, MessageVariant.NORMAL);
            case CLAN_GIM_MESSAGE:
                return gimNotification(raw);
            case CLAN_GIM_CHAT:
                return inGim ? Result.of(stripLeadingPipe(raw), MessageVariant.GIM) : untouched(raw);
            case CLAN_CHAT:
                if (inGim && raw.startsWith("|")) {
                    return Result.of(stripLeadingPipe(raw), MessageVariant.GIM);
                }
                return untouched(raw);
            case BROADCAST:
                return broadcast(raw, broadcastUrlLookup);
            default:
                return untouched(raw);
        }
    }

    /** Restore only the transport prefix RuneLite removes from synthetic GIM event types. */
    public static Result parseEvent(ChatMessageType type, String text, boolean inGim,
            IntFunction<String> broadcastUrlLookup) {
        String raw = type == ChatMessageType.CLAN_GIM_CHAT || type == ChatMessageType.CLAN_GIM_MESSAGE
                ? "|" + text : text;
        return parse(type, raw, inGim, broadcastUrlLookup);
    }

    private static Result untouched(String raw) {
        return Result.of(raw, MessageVariant.NORMAL);
    }

    /** GIM form {@code [|]text} or {@code [|]CA_ID:n|text}: strip a leading pipe, then split again. */
    private static Result gimNotification(String raw) {
        return splitShowRight(stripLeadingPipe(raw), MessageVariant.GIM);
    }

    /** Splits at the first {@code |} when present, showing the right side; left side may carry a task id. */
    private static Result splitShowRight(String text, MessageVariant variant) {
        int pipe = text.indexOf('|');
        if (pipe < 0) {
            return Result.of(text, variant);
        }
        String left = text.substring(0, pipe);
        return new Result(text.substring(pipe + 1), variant, parseTaskId(left), null);
    }

    private static Result broadcast(String raw, IntFunction<String> urlLookup) {
        int pipe = raw.indexOf('|');
        if (pipe < 0) {
            return untouched(raw);
        }
        String left = raw.substring(0, pipe);
        String right = raw.substring(pipe + 1);
        if (right.isEmpty()) {
            return untouched(left);
        }
        int key = BROADCAST_KEYS.indexOf(right.charAt(0));
        String url = key < 0 ? null : urlLookup.apply(key);
        if (url == null || url.isEmpty()) {
            return untouched(left);
        }
        return new Result(BROADCAST_ICON + left, MessageVariant.NORMAL, null, url);
    }

    /** cs2 finds {@code CA_ID:} anywhere in the left side and reads the int after it. */
    private static Integer parseTaskId(String left) {
        int idx = left.indexOf(CA_ID_PREFIX);
        if (idx < 0) {
            return null;
        }
        String digits = left.substring(idx + CA_ID_PREFIX.length());
        if (!digits.matches("\\d{1,9}")) {
            return null;
        }
        return Integer.parseInt(digits);
    }

    private static String stripLeadingPipe(String text) {
        return text.startsWith("|") ? text.substring(1) : text;
    }
}

package com.chatwidgets;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.Color;

/**
 * Global plugin settings exposed in RuneLite's config panel. These apply to all overlays.
 * Per-overlay settings (message types, fade, position, etc.) are managed separately via
 * {@link com.chatwidgets.overlay.OverlayConfig} and the sidebar panel.
 */
@ConfigGroup("chatwidgets")
public interface ChatWidgetConfig extends Config {

    @ConfigItem(keyName = "hideSidePanel", name = "Hide Side Panel", description = "Hide the Chat Widgets panel from the sidebar", position = -1)
    default boolean hideSidePanel() {
        return false;
    }

    @ConfigSection(name = "Appearance", description = "Global appearance settings shared across all widgets", position = 0, closedByDefault = false)
    String appearanceSection = "appearance";

    @ConfigSection(name = "Message Colours", description = "Text colour per message category", position = 1, closedByDefault = false)
    String coloursSection = "colours";

    @ConfigItem(keyName = "textShadow", name = "Text Shadow", description = "Draw shadow behind text", section = appearanceSection, position = 1)
    default boolean textShadow() {
        return true;
    }

    @ConfigItem(keyName = "wrapText", name = "Wrap Text", description = "Wrap long messages to multiple lines", section = appearanceSection, position = 2)
    default boolean wrapText() {
        return true;
    }

    @ConfigItem(keyName = "hidePrivateChat", name = "Hide Default Private Chat", description = "Hide the default split private chat widget", section = appearanceSection, position = 3)
    default boolean hidePrivateChat() {
        return true;
    }

    @ConfigItem(keyName = "smartPositioning", name = "Smart Positioning", description = "Automatically reposition widgets based on client mode and chatbox state", section = appearanceSection, position = 4)
    default boolean smartPositioning() {
        return true;
    }

    @ConfigItem(keyName = "collapseDuplicates", name = "Collapse Duplicates", description = "Merge consecutive identical messages into one with a count", section = appearanceSection, position = 5)
    default boolean collapseDuplicates() {
        return false;
    }

    @ConfigItem(keyName = "showChannelName", name = "Show Channel Names", description = "Show the channel name prefix for friends and clan chat messages, and the clan tag on clan notifications", section = appearanceSection, position = 6)
    default boolean showChannelName() {
        return true;
    }

    @ConfigItem(keyName = "useChatFilter", name = "Use Chat Filter", description = "Hide/censor messages using RuneLite's Chat Filter plugin's word & regex lists and Filter Type", section = appearanceSection, position = 7)
    default boolean useChatFilter() {
        return false;
    }

    @ConfigItem(keyName = "timestampFormat", name = "Timestamp Format", description = "Format for timestamps, shared by all widgets (e.g. [HH:mm:ss], [HH:mm]). Enable timestamps per widget in the side panel.", section = appearanceSection, position = 8)
    default String timestampFormat() {
        return "[HH:mm]";
    }

    @ConfigItem(keyName = "gameColour", name = "Game", description = "Text colour for game messages", section = coloursSection, position = 1)
    default Color gameColour() {
        return Color.WHITE;
    }

    @ConfigItem(keyName = "publicColour", name = "Public", description = "Text colour for public chat messages", section = coloursSection, position = 2)
    default Color publicColour() {
        return new Color(148, 148, 255);
    }

    @ConfigItem(keyName = "privateColour", name = "Private", description = "Text colour for private messages", section = coloursSection, position = 3)
    default Color privateColour() {
        return new Color(0, 255, 255);
    }

    @ConfigItem(keyName = "friendsColour", name = "Friends", description = "Text colour for friends chat messages", section = coloursSection, position = 4)
    default Color friendsColour() {
        return new Color(239, 80, 80);
    }

    @ConfigItem(keyName = "clanColour", name = "Clan", description = "Text colour for clan chat messages", section = coloursSection, position = 5)
    default Color clanColour() {
        return new Color(127, 0, 0);
    }

    @ConfigItem(keyName = "guestClanColour", name = "Guest Clan", description = "Text colour for guest clan chat messages", section = coloursSection, position = 6)
    default Color guestClanColour() {
        return new Color(0, 211, 0);
    }

    @ConfigItem(keyName = "gimClanColour", name = "GIM Clan", description = "Text colour for Group Ironman clan chat messages", section = coloursSection, position = 7)
    default Color gimClanColour() {
        return new Color(127, 0, 0);
    }

    @ConfigItem(keyName = "tradeColour", name = "Trade", description = "Text colour for trade messages", section = coloursSection, position = 8)
    default Color tradeColour() {
        return new Color(223, 32, 255);
    }

    @ConfigItem(keyName = "challengeColour", name = "Challenge", description = "Text colour for challenge request messages", section = coloursSection, position = 9)
    default Color challengeColour() {
        return new Color(255, 32, 223);
    }

    @ConfigItem(keyName = "didYouKnowColour", name = "Did You Know?", description = "Text colour for Did You Know messages", section = coloursSection, position = 10)
    default Color didYouKnowColour() {
        return new Color(255, 255, 0);
    }

    @ConfigItem(keyName = "broadcastColour", name = "Broadcast", description = "Text colour for broadcast messages", section = coloursSection, position = 11)
    default Color broadcastColour() {
        return Color.WHITE;
    }

    @ConfigItem(keyName = "autoColour", name = "Autochat", description = "Text colour for autochat messages", section = coloursSection, position = 12)
    default Color autoColour() {
        return new Color(64, 64, 255);
    }
}

package com.chatwidgets;

import com.chatwidgets.model.FontSize;
import com.chatwidgets.model.MessageCategory;
import com.chatwidgets.model.WidgetPosition;
import com.chatwidgets.overlay.OverlayConfig;
import net.runelite.api.ChatMessageType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;

import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.image.BufferedImage;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * RuneLite sidebar panel for managing overlay widgets. Users can add, delete, reorder,
 * and configure overlays here.
 */
public class ChatWidgetPanel extends PluginPanel {

    private final ChatWidgetPlugin plugin;
    private final Map<String, Boolean> collapsedState = new HashMap<>();
    private JComponent debugSection;
    private boolean debugCollapsed = true;

    public ChatWidgetPanel(ChatWidgetPlugin plugin) {
        super(false);
        this.plugin = plugin;
        rebuild();
    }

    /** Shows a dev-only Debug section below the widgets, or removes it when null. */
    public void setDebugSection(JComponent section) {
        debugSection = section;
        rebuild();
    }

    public void rebuild() {
        removeAll();
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Header with add button
        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        headerPanel.setBorder(new EmptyBorder(8, 4, 4, 4));
        headerPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel title = new JLabel("Chat Widgets");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(Font.BOLD));
        headerPanel.add(title, BorderLayout.WEST);

        JPanel headerButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        headerButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JButton supportButton = new JButton();
        BufferedImage supportIcon = ImageUtil.loadImageResource(ChatWidgetPanel.class, "/support.png");
        if (supportIcon != null) {
            supportButton.setIcon(new ImageIcon(supportIcon));
        }
        supportButton.setFocusPainted(false);
        supportButton.setToolTipText("Support");
        supportButton.setMargin(new Insets(1, 6, 1, 6));
        supportButton.addActionListener(e -> LinkBrowser.browse("https://buymeacoffee.com/cnnnr"));

        JButton addButton = new JButton("+");
        addButton.setToolTipText("Add new widget");
        addButton.setFocusPainted(false);
        addButton.addActionListener(e -> plugin.addNewOverlay());
        headerButtons.add(addButton);

        JButton resetButton = new JButton("⟳");
        resetButton.setFocusPainted(false);
        resetButton.setToolTipText("Reset to the default widgets");
        resetButton.setMargin(new Insets(1, 6, 1, 6));
        resetButton.addActionListener(e -> {
            int result = JOptionPane.showConfirmDialog(this,
                    "Delete all chat widgets and restore the default 2?",
                    "Reset Chat Widgets", JOptionPane.YES_NO_OPTION);
            if (result == JOptionPane.YES_OPTION) {
                plugin.resetOverlays();
            }
        });
        headerButtons.add(resetButton);
        headerButtons.add(supportButton);

        headerPanel.add(headerButtons, BorderLayout.EAST);

        contentPanel.add(headerPanel);

        // Overlay sections
        for (OverlayConfig oc : plugin.getOverlayConfigs()) {
            contentPanel.add(buildOverlaySection(oc));
        }

        if (debugSection != null) {
            contentPanel.add(buildDebugSection());
        }

        // Wrap in a top-aligned container so items don't stretch vertically
        JPanel wrapper = new JPanel(new BorderLayout());
        wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        wrapper.add(contentPanel, BorderLayout.NORTH);

        JScrollPane scrollPane = new JScrollPane(wrapper);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(null);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        add(scrollPane, BorderLayout.CENTER);

        revalidate();
        repaint();
    }

    private JPanel buildOverlaySection(OverlayConfig oc) {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        section.setAlignmentX(Component.LEFT_ALIGNMENT);
        section.setBorder(new CompoundBorder(
                new MatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
                new EmptyBorder(4, 4, 4, 4)
        ));

        boolean collapsed = collapsedState.getOrDefault(oc.getId(), true);

        // Collapsible header row
        JPanel headerRow = new JPanel(new BorderLayout());
        headerRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        headerRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        headerRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        headerRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        JLabel arrow = new JLabel(collapsed ? "⮞ " : "⮟ ");
        arrow.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        JLabel nameLabel = new JLabel(oc.getName());
        nameLabel.setForeground(oc.isShow() ? Color.WHITE : new Color(255, 255, 255, 100));
        nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD));

        JPanel namePanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        namePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        namePanel.add(arrow);
        namePanel.add(nameLabel);
        headerRow.add(namePanel, BorderLayout.CENTER);

        JPanel orderButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        orderButtons.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JLabel upBtn = new JLabel("\uD83E\uDC25");
        upBtn.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        upBtn.setBorder(new EmptyBorder(0, 3, 0, 3));
        upBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        upBtn.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseReleased(java.awt.event.MouseEvent e) {
                plugin.moveOverlay(oc, -1);
            }
        });

        JLabel downBtn = new JLabel("\uD83E\uDC27");
        downBtn.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        downBtn.setBorder(new EmptyBorder(0, 3, 0, 3));
        downBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        downBtn.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseReleased(java.awt.event.MouseEvent e) {
                plugin.moveOverlay(oc, 1);
            }
        });

        orderButtons.add(upBtn);
        orderButtons.add(downBtn);
        headerRow.add(orderButtons, BorderLayout.EAST);

        // Content panel (everything below the header)
        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        content.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.setVisible(!collapsed);

        headerRow.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseReleased(java.awt.event.MouseEvent e) {
                boolean nowCollapsed = !collapsedState.getOrDefault(oc.getId(), false);
                collapsedState.put(oc.getId(), nowCollapsed);
                content.setVisible(!nowCollapsed);
                arrow.setText(nowCollapsed ? "⮞ " : "⮟ ");
                section.revalidate();
                section.repaint();
            }
        });

        section.add(headerRow);
        content.add(createStrut(4));

        // Title (editable name)
        content.add(buildTitleRow(oc, nameLabel));

        // Show toggle
        content.add(buildCheckbox("Show", oc.isShow(), v -> {
            oc.setShow(v);
            nameLabel.setForeground(v ? Color.WHITE : new Color(255, 255, 255, 100));
            plugin.onOverlayConfigChanged();
        }));

        // Message types - inline row like other settings
        content.add(buildMessageTypeRow(oc));

        // Settings rows
        content.add(buildCheckbox("Always Visible", oc.isAlwaysVisible(), v -> {
            oc.setAlwaysVisible(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildCheckbox("Contextual Colours", oc.isContextualColours(), v -> {
            oc.setContextualColours(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildColorRow("Background", oc::getBackgroundColour, oc::setBackgroundColour));
        content.add(buildCheckbox("Show Timestamps", oc.isShowTimestamp(), v -> {
            oc.setShowTimestamp(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildCheckbox("Show Input Preview", oc.isShowInputPreview(), v -> {
            oc.setShowInputPreview(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildCheckbox("Preview Only While Typing", oc.isPreviewOnlyWhenTyping(), v -> {
            oc.setPreviewOnlyWhenTyping(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildComboRow("Font Size", FontSize.values(), oc.getFontSize(), v -> {
            oc.setFontSize(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildSpinnerRow("Max Messages", oc.getMaxMessages(), 1, 20, v -> {
            oc.setMaxMessages(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildSpinnerRow("Fade Out (sec)", oc.getFadeOutDuration(), 0, 300, v -> {
            oc.setFadeOutDuration(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildComboRow("Position", WidgetPosition.values(), oc.getPosition(), v -> {
            oc.setPosition(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildCheckbox("Dynamic Height", oc.isDynamicHeight(), v -> {
            oc.setDynamicHeight(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildSpinnerRow("Margin Top", oc.getMarginTop(), 0, 200, v -> {
            oc.setMarginTop(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildSpinnerRow("Margin Bottom", oc.getMarginBottom(), 0, 200, v -> {
            oc.setMarginBottom(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildSpinnerRow("Margin Left", oc.getMarginLeft(), 0, 200, v -> {
            oc.setMarginLeft(v);
            plugin.onOverlayConfigChanged();
        }));
        content.add(buildSpinnerRow("Margin Right", oc.getMarginRight(), 0, 200, v -> {
