package com.chatwidgets.overlay;

import com.chatwidgets.model.FontSize;
import com.chatwidgets.model.WidgetMessage;
import net.runelite.api.ChatMessageType;
import net.runelite.api.IndexedSprite;
import net.runelite.client.config.ChatColorConfig;
import net.runelite.client.ui.FontManager;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Stateless rendering utilities shared by all overlays. Handles two main concerns:
 *
 * <p><b>Text parsing</b> — Converts raw message strings containing OSRS markup into lists of
 * {@link TextSegment}s. Two parsers exist:
 * <ul>
 *   <li>{@link #parseTextWithIcons} — handles {@code <img=N>} icon tags and entity references
 *       ({@code <lt>}, {@code <gt>}). Used for sender names.</li>
 *   <li>{@link #parseTextWithColoursAndIcons}: additionally handles the game font's formatting
 *       tags ({@code <col>}, {@code <str>}, {@code <u>}, {@code <shad>}, {@code <br>}), named
 *       colour tags, and {@code <str_NAME=VALUE>} template variables. Used for message bodies.</li>
 * </ul>
 *
 * <p><b>Icon caching</b> — Converts RuneLite's {@link IndexedSprite} mod icons to
 * {@link BufferedImage} on first access and caches them. The cache is invalidated when
 * the modIcons array reference changes (e.g. after a plugin loads new icons).
 */
public final class ChatRenderUtils {

    private static final Pattern IMG_TAG_PATTERN = Pattern.compile("<img=(\\d+)>");
    private static final Pattern TEMPLATE_DEF_PATTERN = Pattern.compile("<(str_[^=<>]+)=([^<>]*)>");
    private static final Pattern TEMPLATE_REF_PATTERN = Pattern.compile("<(str_[^=<>]+)>");
    private static final int MAX_MESSAGE_LENGTH = 500;
    /** The game font's strikethrough colour for a bare {@code <str>} tag. */
    private static final Color DEFAULT_STRIKE_COLOR = new Color(0x800000);
    private static final Color CHANNEL_NAME_COLOUR = new Color(144, 144, 255);
    // cs2 rebuildchatbox colours "Broadcast:" 0x30ff30 on the transparent chatbox.
    private static final Color BROADCAST_LABEL_COLOUR = new Color(0x30ff30);
    private static final String BROADCAST_LABEL = "Broadcast: ";

    private static IndexedSprite[] cachedModIconsRef;
    private static final Map<Integer, BufferedImage> iconImageCache = new HashMap<>();

    private static final Set<ChatMessageType> SENDER_PREFIX_TYPES = EnumSet.of(
            ChatMessageType.PRIVATECHAT,
            ChatMessageType.PRIVATECHATOUT,
            ChatMessageType.MODPRIVATECHAT,
            ChatMessageType.PUBLICCHAT,
            ChatMessageType.MODCHAT,
            ChatMessageType.AUTOTYPER,
            ChatMessageType.MODAUTOTYPER,
            ChatMessageType.FRIENDSCHAT,
            ChatMessageType.CLAN_CHAT,
            ChatMessageType.CLAN_GUEST_CHAT,
            ChatMessageType.CLAN_GIM_CHAT
    );

    private static final Set<ChatMessageType> PM_TYPES = EnumSet.of(
            ChatMessageType.PRIVATECHAT,
            ChatMessageType.PRIVATECHATOUT,
            ChatMessageType.MODPRIVATECHAT
    );

    private ChatRenderUtils() {
    }

    public static FontMetrics setupGraphics(Graphics2D graphics, FontSize fontSize) {
        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
        graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

        Font baseFont = fontSize == FontSize.SMALL
                ? FontManager.getRunescapeSmallFont()
                : FontManager.getRunescapeFont();
        graphics.setFont(baseFont);
        return graphics.getFontMetrics();
    }

    public static int drawIcon(Graphics2D graphics, BufferedImage img, FontSize fontSize,
            FontMetrics metrics, int x, int y) {
        if (img == null) {
            return 0;
        }
        boolean isSmallFont = fontSize == FontSize.SMALL;
        int iconWidth = img.getWidth();
        int iconHeight = img.getHeight();

        if (isSmallFont) {
            iconWidth = (int) (iconWidth * 0.75);
            iconHeight = (int) (iconHeight * 0.75);
        }

        int iconY = y - iconHeight + metrics.getDescent() - 4;
        if (isSmallFont) {
            iconY += 2;
        }

        graphics.drawImage(img, x + 1, iconY, iconWidth, iconHeight, null);
        return iconWidth + 2;
    }

    /**
     * Draws a text segment with its font decorations, matching the game's font renderer: the
     * shadow is offset one pixel right and down, the strikethrough sits 70% of the ascent below
     * the glyph top, and the underline one pixel below the baseline. A segment without its own
     * shadow colour uses the base shadow ({@code drawShadow}: black or none).
     */
    public static int drawText(Graphics2D graphics, TextSegment segment, Color color, int alpha, int x, int y,
            boolean drawShadow, FontMetrics metrics) {
        String text = segment.text;
        int width = metrics.stringWidth(text);
        Color shadow = segment.shadowColor != null ? segment.shadowColor : (drawShadow ? Color.BLACK : null);
        if (shadow != null) {
            graphics.setColor(withAlpha(shadow, alpha));
            graphics.drawString(text, x + 2, y + 1);
        }
        graphics.setColor(withAlpha(color, alpha));
        graphics.drawString(text, x + 1, y);
        if (segment.strikeColor != null) {
            graphics.setColor(withAlpha(segment.strikeColor, alpha));
            graphics.fillRect(x + 1, y - metrics.getAscent() + (int) (metrics.getAscent() * 0.7), width, 1);
        }
        if (segment.underlineColor != null) {
            graphics.setColor(withAlpha(segment.underlineColor, alpha));
            graphics.fillRect(x + 1, y + 1, width, 1);
        }
        return width;
    }

    public static int calculateAlpha(WidgetMessage msg, long currentTime, long fadeOutMs) {
        if (fadeOutMs <= 0) {
            return 255;
        }
        long age = currentTime - msg.getTimestamp();
        if (age <= fadeOutMs) {
            return 255;
        }
        double fadeProgress = Math.min(1.0, (age - fadeOutMs) / 1200.0);
        return (int) (255 * (1.0 - fadeProgress));
    }

    public static Color withAlpha(Color color, int alpha) {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
    }

    /**
     * Returns a cached BufferedImage for the given mod icon index.
     * Converts and caches on first access; clears cache when the modIcons array reference changes.
     */
    public static BufferedImage getModIconImage(int iconId, IndexedSprite[] modIcons) {
        if (modIcons == null || iconId < 0 || iconId >= modIcons.length) {
            return null;
        }

        if (modIcons != cachedModIconsRef) {
            iconImageCache.clear();
            cachedModIconsRef = modIcons;
        }

        if (iconImageCache.containsKey(iconId)) {
            return iconImageCache.get(iconId);
        }

        BufferedImage img = indexedSpriteToImage(modIcons[iconId]);
        iconImageCache.put(iconId, img);
        return img;
    }

    public static BufferedImage indexedSpriteToImage(IndexedSprite sprite) {
        if (sprite == null) {
            return null;
        }
        try {
            int width = sprite.getWidth();
            int height = sprite.getHeight();
            if (width <= 0 || height <= 0) {
                return null;
            }
            byte[] pixels = sprite.getPixels();
            int[] palette = sprite.getPalette();
            if (pixels == null || palette == null || palette.length == 0) {
                return null;
            }
            int totalPixels = Math.min(pixels.length, width * height);
            BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
            int[] imgPixels = ((DataBufferInt) img.getRaster().getDataBuffer()).getData();
            for (int i = 0; i < totalPixels; i++) {
                int index = pixels[i] & 0xFF;
                if (index != 0 && index < palette.length) {
                    imgPixels[i] = palette[index] | 0xFF000000;
                }
            }
            return img;
        } catch (Exception e) {
            return null;
        }
    }

    public static String formatTimestamp(long timestamp, String format) {
        try {
            return new SimpleDateFormat(format).format(new Date(timestamp));
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    /**
     * Builds render lines for any message type. Handles sender prefixes for PMs,
     * public chat, friends chat, and clan chat automatically based on the message type.
     */
    public static List<RenderLine> buildMessageLines(WidgetMessage msg, FontMetrics metrics,
            int widgetWidth, long currentTime, long fadeOutMs, boolean wrapText, Color textColor,
            boolean retainContextualColours, boolean hideDuplicateCount,
            FontSize fontSize, IndexedSprite[] modIcons, boolean showTimestamp, String timestampFormat,
            boolean showChannelName, ChatColorConfig chatColorConfig) {

        List<RenderLine> lines = new ArrayList<>();
        int alpha = calculateAlpha(msg, currentTime, fadeOutMs);

        ChatMessageType type = msg.getType();
        boolean hasSenderPrefix = SENDER_PREFIX_TYPES.contains(type);
        boolean isPm = PM_TYPES.contains(type);
        boolean isLoginNotification = type == ChatMessageType.LOGINLOGOUTNOTIFICATION;

        // Build header (timestamp + optional sender prefix)
        List<TextSegment> headerSegments = new ArrayList<>();
        int headerWidth = 0;

        if (showTimestamp && timestampFormat != null && !timestampFormat.isEmpty()) {
            String ts = formatTimestamp(msg.getTimestamp(), timestampFormat + " ");
            if (ts != null) {
                int width = metrics.stringWidth(ts);
                Color tsColor = retainContextualColours ? Color.WHITE : textColor;
                headerSegments.add(new TextSegment(ts, -1, width, tsColor));
                headerWidth += width;
            }
        }

        if (hasSenderPrefix && !isLoginNotification && msg.getSender() != null) {
            Color nameColor = retainContextualColours ? Color.WHITE : textColor;
            if (isPm) {
                String prefix = msg.isOutgoing() ? "To " : "From ";
                headerSegments.add(new TextSegment(prefix, -1, metrics.stringWidth(prefix), textColor));
                headerWidth += metrics.stringWidth(prefix);
            }

            if (showChannelName) {
                headerWidth += addChannelTag(headerSegments, msg.getChannelName(), metrics,
                        retainContextualColours, textColor);
            }

            List<TextSegment> senderSegments = parseTextWithIcons(msg.getSender(), metrics, modIcons,
                    nameColor, fontSize);
            for (TextSegment seg : senderSegments) {
                headerSegments.add(seg);
                headerWidth += seg.width;
            }

            headerSegments.add(new TextSegment(": ", -1, metrics.stringWidth(": "), nameColor));
            headerWidth += metrics.stringWidth(": ");
        } else if (type == ChatMessageType.BROADCAST) {
            // Always shown, like the chatbox's label (not a channel name, so not toggleable).
            Color labelColor = retainContextualColours ? BROADCAST_LABEL_COLOUR : textColor;
            headerSegments.add(new TextSegment(BROADCAST_LABEL, -1, metrics.stringWidth(BROADCAST_LABEL), labelColor));
            headerWidth += metrics.stringWidth(BROADCAST_LABEL);
        } else if (showChannelName) {
            // Clan notifications: [clan name], [GIM group name] or [PvP Arena], snapshotted at capture.
            headerWidth += addChannelTag(headerSegments, msg.getClanTag(), metrics,
                    retainContextualColours, textColor);
        }

        // Build message body
        // Expand templates before truncating, so a long definition can't push its value past the cut.
        String messageText = expandTemplates(msg.getMessage());
        if (messageText != null && messageText.length() > MAX_MESSAGE_LENGTH) {
            messageText = messageText.substring(0, MAX_MESSAGE_LENGTH) + "...";
        }

        if (msg.getCount() > 1 && !hideDuplicateCount) {
            messageText = messageText + " (" + msg.getCount() + ")";
        }

        List<TextSegment> messageSegments = parseTextWithColoursAndIcons(messageText, metrics, modIcons,
                retainContextualColours, textColor, fontSize, chatColorConfig);

        if (!wrapText) {
            List<TextSegment> singleLine = new ArrayList<>(headerSegments);
            singleLine.addAll(messageSegments);
            lines.add(new RenderLine(singleLine, alpha));
        } else {
            int firstLineRemaining = widgetWidth - headerWidth;
            List<List<TextSegment>> wrappedLines = wrapSegments(messageSegments, metrics,
                    firstLineRemaining, widgetWidth, textColor);
            addWrappedLines(lines, alpha, headerSegments, wrappedLines);
        }

        return lines;
    }

    /**
     * Appends a {@code [name] } channel tag to {@code segments}, coloured like the chatbox's channel
     * names. No-op for a null or empty name.
     *
     * @return the width added
     */
    private static int addChannelTag(List<TextSegment> segments, String name, FontMetrics metrics,
            boolean retainContextualColours, Color textColor) {
        if (name == null || name.isEmpty()) {
            return 0;
        }
        Color bracketColor = retainContextualColours ? Color.WHITE : textColor;
        Color channelTextColor = retainContextualColours ? CHANNEL_NAME_COLOUR : textColor;

        String open = "[";
        String close = "] ";
        int openWidth = metrics.stringWidth(open);
        int nameWidth = metrics.stringWidth(name);
        int closeWidth = metrics.stringWidth(close);
        segments.add(new TextSegment(open, -1, openWidth, bracketColor));
        segments.add(new TextSegment(name, -1, nameWidth, channelTextColor));
        segments.add(new TextSegment(close, -1, closeWidth, bracketColor));
        return openWidth + nameWidth + closeWidth;
    }

    public static void addWrappedLines(List<RenderLine> lines, int alpha, List<TextSegment> headerSegments,
            List<List<TextSegment>> wrappedLines) {
        if (wrappedLines.isEmpty()) {
            lines.add(new RenderLine(headerSegments, alpha));
        } else {
            List<TextSegment> firstLine = new ArrayList<>(headerSegments);
            firstLine.addAll(wrappedLines.get(0));
            lines.add(new RenderLine(firstLine, alpha));

            for (int i = 1; i < wrappedLines.size(); i++) {
                lines.add(new RenderLine(wrappedLines.get(i), alpha));
            }
        }
    }

    public static int calculateIconWidth(IndexedSprite[] modIcons, int iconId, FontSize fontSize) {
        int iconWidth = 13;
        if (modIcons != null && iconId >= 0 && iconId < modIcons.length && modIcons[iconId] != null) {
            iconWidth = modIcons[iconId].getWidth() + 1;
            if (fontSize == FontSize.SMALL) {
                iconWidth = (int) (iconWidth * 0.75);
            }
        }
        return iconWidth;
    }

    public static List<TextSegment> parseTextWithIcons(String text, FontMetrics metrics,
            IndexedSprite[] modIcons, Color textColor, FontSize fontSize) {
        List<TextSegment> segments = new ArrayList<>();
        if (text == null || text.isEmpty()) {
            return segments;
        }

        text = text.replace("<lt>", "<").replace("<gt>", ">").replace("<at>", "@");

        Matcher matcher = IMG_TAG_PATTERN.matcher(text);
        int lastEnd = 0;

        while (matcher.find()) {
            if (matcher.start() > lastEnd) {
                String before = text.substring(lastEnd, matcher.start());
                segments.add(new TextSegment(before, -1, metrics.stringWidth(before), textColor));
            }

            try {
                int iconId = Integer.parseInt(matcher.group(1));
                int iconWidth = calculateIconWidth(modIcons, iconId, fontSize);
                segments.add(new TextSegment("", iconId, iconWidth, textColor));
            } catch (NumberFormatException e) {
                String raw = matcher.group(0);
                segments.add(new TextSegment(raw, -1, metrics.stringWidth(raw), textColor));
            }
            lastEnd = matcher.end();
        }

        if (lastEnd < text.length()) {
            String after = text.substring(lastEnd);
            segments.add(new TextSegment(after, -1, metrics.stringWidth(after), textColor));
        }

        return segments;
    }

    /**
     * Parses text with full chat formatting tag support, icon tags, and line breaks.
     * Used for system/game messages that can contain formatting. Tags follow the game's font
     * renderer ({@code AbstractFont.decodeTag}): only {@code col=}, {@code str=}, {@code u=},
     * {@code shad=} and {@code img=} are prefix matches, every bare tag must match exactly, and any
     * unrecognised tag is skipped silently. Template variables are expanded first (see
     * {@link #expandTemplates}). {@code retainContextualColours} gates only the text colour
     * ({@code <col>} tags); strikethrough, underline and shadow always keep their tag colours.
     */
    public static List<TextSegment> parseTextWithColoursAndIcons(String text, FontMetrics metrics,
            IndexedSprite[] modIcons, boolean retainContextualColours, Color textColor,
            FontSize fontSize, ChatColorConfig chatColorConfig) {
        List<TextSegment> segments = new ArrayList<>();
        if (text == null || text.isEmpty()) {
            return segments;
        }

        text = expandTemplates(text);
        SegmentBuilder builder = new SegmentBuilder(segments, metrics, textColor);
        int i = 0;

        while (i < text.length()) {
            char c = text.charAt(i);
            int tagEnd = c == '<' ? text.indexOf('>', i + 1) : -1;
            if (tagEnd < 0) {
                builder.append(c);
                i++;
                continue;
            }

            String tag = text.substring(i + 1, tagEnd);
            i = tagEnd + 1;

            if (tag.equals("br") || tag.equals("n")) {
                builder.lineBreak();
            } else if (tag.equals("lt")) {
                builder.append('<');
            } else if (tag.equals("gt")) {
                builder.append('>');
            } else if (tag.equals("nbh")) {
                builder.append('-');
            } else if (tag.equals("at")) {
                // RuneLite escapes a literal '@' as <at> so it isn't parsed as an @col@ colour code.
                builder.append('@');
            } else if (tag.equals("colNORMAL")) {
                builder.setColor(textColor);
            } else if (tag.equals("colHIGHLIGHT")) {
                if (chatColorConfig != null) {
                    Color highlight = chatColorConfig.transparentExamineHighlight();
                    builder.setColor(highlight != null ? highlight : textColor);
                }
            } else if (tag.startsWith("col=")) {
                Color color = parseHexColor(tag.substring(4));
                if (color != null && retainContextualColours) {
                    builder.setColor(color);
                }
            } else if (tag.equals("/col")) {
                if (retainContextualColours) {
                    builder.setColor(textColor);
                }
            } else if (tag.equals("str")) {
                builder.setStrike(DEFAULT_STRIKE_COLOR);
            } else if (tag.startsWith("str=")) {
                Color color = parseHexColor(tag.substring(4));
                if (color != null) {
                    builder.setStrike(color);
                }
            } else if (tag.equals("/str")) {
                builder.setStrike(null);
            } else if (tag.equals("u")) {
                builder.setUnderline(Color.BLACK);
            } else if (tag.startsWith("u=")) {
                Color color = parseHexColor(tag.substring(2));
                if (color != null) {
                    builder.setUnderline(color);
                }
            } else if (tag.equals("/u")) {
                builder.setUnderline(null);
            } else if (tag.equals("shad")) {
                builder.setShadow(Color.BLACK);
            } else if (tag.startsWith("shad=")) {
                Color color = parseHexColor(tag.substring(5));
                if (color != null) {
                    builder.setShadow(color);
                }
            } else if (tag.equals("/shad")) {
                builder.setShadow(null);
            } else if (tag.startsWith("img=")) {
                Integer iconId = parseIconId(tag.substring(4));
                if (iconId != null) {
                    builder.icon(iconId, calculateIconWidth(modIcons, iconId, fontSize));
                }
            }
            // Any other tag (e.g. <html>) is invisible in-game: skip it.
        }

        builder.flush();
        return segments;
    }

    /** Returns the icon id, or null if it isn't a number (the game's font then ignores the tag). */
    private static Integer parseIconId(String id) {
        try {
            int iconId = Integer.parseInt(id);
            return iconId >= 0 ? iconId : null;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static Color parseHexColor(String hex) {
        try {
            return new Color(Integer.parseInt(hex, 16));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** Accumulates text under the current formatting state, flushing a segment on each change. */
    private static final class SegmentBuilder {
        private final List<TextSegment> segments;
        private final FontMetrics metrics;
        private final Color baseColor;
        private final StringBuilder text = new StringBuilder();
        private Color color;
        private Color strike;
        private Color underline;
        private Color shadow;

        SegmentBuilder(List<TextSegment> segments, FontMetrics metrics, Color baseColor) {
            this.segments = segments;
            this.metrics = metrics;
            this.baseColor = baseColor;
            this.color = baseColor;
        }

        void append(char c) {
            text.append(c);
        }

        void flush() {
            if (text.length() > 0) {
                String str = text.toString();
                segments.add(new TextSegment(str, -1, metrics.stringWidth(str), color,
                        strike, underline, shadow));
                text.setLength(0);
            }
        }

        void setColor(Color newColor) {
            flush();
            color = newColor;
        }

        void setStrike(Color newStrike) {
            flush();
            strike = newStrike;
        }

        void setUnderline(Color newUnderline) {
            flush();
            underline = newUnderline;
        }

        void setShadow(Color newShadow) {
            flush();
            shadow = newShadow;
        }

        void icon(int iconId, int width) {
            flush();
            segments.add(new TextSegment("", iconId, width, color));
        }

        /** A line break, which also resets all formatting to the line's base state. */
        void lineBreak() {
            flush();
            color = baseColor;
            strike = null;
            underline = null;
            shadow = null;
            segments.add(new TextSegment("", TextSegment.LINE_BREAK, 0, color));
        }
    }

    /**
     * Expands the game's template variables: each {@code <str_NAME=VALUE>} definition is removed
     * and every later {@code <str_NAME>} reference is replaced with its value. The client does this
     * before setting chatbox widget text, but the raw template is all RuneLite exposes, so it must
     * run before tag parsing (whose unknown-tag catch-all would otherwise delete the value).
     */
    public static String expandTemplates(String text) {
        if (text == null || !text.contains("<str_")) {
            return text;
        }

        Map<String, String> vars = new HashMap<>();
        Matcher defMatcher = TEMPLATE_DEF_PATTERN.matcher(text);
        StringBuffer withoutDefs = new StringBuffer();
        while (defMatcher.find()) {
            vars.put(defMatcher.group(1), defMatcher.group(2));
            defMatcher.appendReplacement(withoutDefs, "");
        }
        defMatcher.appendTail(withoutDefs);

        Matcher refMatcher = TEMPLATE_REF_PATTERN.matcher(withoutDefs);
        StringBuffer expanded = new StringBuffer();
        while (refMatcher.find()) {
            String value = vars.getOrDefault(refMatcher.group(1), refMatcher.group(0));
            refMatcher.appendReplacement(expanded, Matcher.quoteReplacement(value));
        }
        refMatcher.appendTail(expanded);
        return expanded.toString();
    }

    public static List<List<TextSegment>> wrapSegments(List<TextSegment> segments,
            FontMetrics metrics, int firstLineWidth, int subsequentLineWidth, Color textColor) {
        List<List<TextSegment>> lines = new ArrayList<>();
        List<TextSegment> currentLine = new ArrayList<>();
        int currentWidth = firstLineWidth;

        for (TextSegment segment : segments) {
            if (segment.iconId == TextSegment.LINE_BREAK) {
                if (!currentLine.isEmpty()) {
                    lines.add(currentLine);
                    currentLine = new ArrayList<>();
                }
                currentWidth = subsequentLineWidth;
            } else if (segment.iconId >= 0) {
                if (segment.width <= currentWidth) {
                    currentLine.add(segment);
                    currentWidth -= segment.width;
                } else {
                    if (!currentLine.isEmpty()) {
                        lines.add(currentLine);
                        currentLine = new ArrayList<>();
                        currentWidth = subsequentLineWidth;
                    }
                    currentLine.add(segment);
                    currentWidth -= segment.width;
                }
            } else {
                String[] words = segment.text.split(" ", -1);
                for (int wi = 0; wi < words.length; wi++) {
                    String word = words[wi];
                    if (word.isEmpty() && wi < words.length - 1) {
                        int spaceWidth = metrics.stringWidth(" ");
                        if (spaceWidth <= currentWidth) {
                            currentLine.add(segment.withText(" ", spaceWidth));
                            currentWidth -= spaceWidth;
                        }
                        continue;
                    }

                    int wordWidth = metrics.stringWidth(word);
                    int spaceWidth = metrics.stringWidth(" ");
                    boolean needsSpace = !currentLine.isEmpty() && wi > 0;
                    int neededWidth = wordWidth + (needsSpace ? spaceWidth : 0);

                    if (neededWidth <= currentWidth) {
                        if (needsSpace) {
                            currentLine.add(segment.withText(" ", spaceWidth));
                            currentWidth -= spaceWidth;
                        }
                        currentLine.add(segment.withText(word, wordWidth));
                        currentWidth -= wordWidth;
                    } else {
                        if (!currentLine.isEmpty()) {
                            lines.add(currentLine);
                            currentLine = new ArrayList<>();
                            currentWidth = subsequentLineWidth;
                        }
                        currentLine.add(segment.withText(word, wordWidth));
                        currentWidth -= wordWidth;
                    }
                }
            }
        }

        if (!currentLine.isEmpty()) {
            lines.add(currentLine);
        }
        return lines;
    }
}

package com.chatwidgets.overlay;

import com.chatwidgets.ChatWidgetConfig;
import com.chatwidgets.ChatWidgetPlugin;
import com.chatwidgets.model.FontSize;
import com.chatwidgets.model.MessageCategory;
import com.chatwidgets.model.WidgetMessage;
import com.chatwidgets.model.WidgetPosition;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IndexedSprite;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ChatColorConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;

/**
 * A single chat overlay instance. Each one is backed by an {@link OverlayConfig} that
 * determines which message types it displays, its position mode, fade behaviour, and
 * other per-widget settings.
 *
 * <p>On each frame, the overlay asks the plugin for the filtered message list, builds
 * render lines via {@link ChatRenderUtils#buildMessageLines}, and paints them bottom-up.
 */
public class DynamicChatOverlay extends Overlay {

    private static final int MIN_ZOOM = -22;
    private static final int MAX_ZOOM = 1400;
    private static final int BELOW_OFFSET_MIN_ZOOM = 40;
    private static final int BELOW_OFFSET_MAX_ZOOM = 150;
    private static final int ABOVE_OFFSET_MIN_ZOOM = -40;
    private static final int ABOVE_OFFSET_MAX_ZOOM = -120;

    private final ChatWidgetPlugin plugin;
    private final ChatWidgetConfig globalConfig;
    private final Client client;
    private final ChatColorConfig chatColorConfig;
    private OverlayConfig overlayConfig;

    /**
     * Height returned by the previous {@link #render} call, or 0 when nothing was drawn.
     * {@code OverlayRenderer} lays an overlay out from the size it reported last frame and only
     * resizes its bounds after {@code render()} returns, so this is the height the renderer has
     * actually allotted us on this frame.
     */
    private int lastReportedHeight;

    public DynamicChatOverlay(ChatWidgetPlugin plugin, ChatWidgetConfig globalConfig, Client client,
            ChatColorConfig chatColorConfig, OverlayConfig overlayConfig) {
        this.plugin = plugin;
        this.globalConfig = globalConfig;
        this.client = client;
        this.chatColorConfig = chatColorConfig;
        this.overlayConfig = overlayConfig;
        setPosition(client.isResized() ? OverlayPosition.ABOVE_CHATBOX_RIGHT : OverlayPosition.BOTTOM_LEFT);
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setResizable(true);
        setMovable(true);
        setMinimumSize(150);
        getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, "Clear",
                overlayConfig.getName() + " history"));
    }

    public OverlayConfig getOverlayConfig() {
        return overlayConfig;
    }

    public void setOverlayConfig(OverlayConfig overlayConfig) {
        this.overlayConfig = overlayConfig;
        getMenuEntries().clear();
        getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, "Clear",
                overlayConfig.getName() + " history"));
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!shouldRender()) {
            lastReportedHeight = 0;
            return null;
        }

        FontSize fontSize = overlayConfig.getFontSize();
        FontMetrics metrics = ChatRenderUtils.setupGraphics(graphics, fontSize);
        IndexedSprite[] modIcons = client.getModIcons();

        Dimension preferredSize = getPreferredSize();
        int widgetWidth = (preferredSize != null && preferredSize.width > 0)
                ? preferredSize.width
                : overlayConfig.getWidgetWidth();
        int lineHeight = metrics.getHeight() - (fontSize == FontSize.SMALL ? 2 : 3) + 1;
        long currentTime = System.currentTimeMillis();
        boolean drawShadow = globalConfig.textShadow();
        boolean wrapText = globalConfig.wrapText();
        boolean retainContextualColours = overlayConfig.isContextualColours();
        boolean hideDuplicateCount = overlayConfig.isHideDuplicateCount();
        WidgetPosition positionMode = overlayConfig.getPosition();
        boolean followPlayer = positionMode != WidgetPosition.WIDGET;
        boolean useDynamicHeight = followPlayer || overlayConfig.isDynamicHeight();

        int fadeOutDuration = overlayConfig.getFadeOutDuration();
        long fadeOutMs = fadeOutDuration * 1000L;
        long fadeOutThreshold = fadeOutMs + 5000;
        int maxMessages = overlayConfig.getMaxMessages();

        List<WidgetMessage> messages = plugin.getMessagesForOverlay(overlayConfig);
        int messageCount = messages.size();
        int startIndex = Math.max(0, messageCount - maxMessages);

        List<RenderLine> renderableLines = new ArrayList<>();
        for (int i = startIndex; i < messageCount; i++) {
            WidgetMessage msg = messages.get(i);

            if (fadeOutDuration == 0 || (currentTime - msg.getTimestamp()) < fadeOutThreshold) {
                Color msgColor = getCategoryColour(msg.getType());
                List<RenderLine> msgLines = ChatRenderUtils.buildMessageLines(msg, metrics,
                        widgetWidth, currentTime, fadeOutMs, wrapText, msgColor,
                        retainContextualColours, hideDuplicateCount,
                        fontSize, modIcons,
                        overlayConfig.isShowTimestamp(), globalConfig.timestampFormat(),
                        globalConfig.showChannelName(),
                        chatColorConfig);

                for (RenderLine line : msgLines) {
                    if (line.alpha > 0) {
                        renderableLines.add(line);
                    }
                }
            }
        }

        // Live input preview line, drawn at the very bottom of the widget when enabled.
        List<TextSegment> inputSegments = buildInputPreviewSegments(metrics, fontSize, modIcons);

        if (renderableLines.isEmpty() && inputSegments == null) {
            lastReportedHeight = 0;
            return null;
        }

        Color background = overlayConfig.getBackgroundColour();
        int bgPadding = background.getAlpha() > 0 ? 3 : 0;

        int inputExtra = inputSegments != null ? lineHeight : 0;
        int widgetHeight;
        if (useDynamicHeight) {
            widgetHeight = renderableLines.size() * lineHeight + inputExtra;
        } else {
            widgetHeight = maxMessages * lineHeight + inputExtra;
        }

        int marginTop = overlayConfig.getMarginTop();
        int marginBottom = overlayConfig.getMarginBottom();
        int marginLeft = overlayConfig.getMarginLeft();
        int marginRight = overlayConfig.getMarginRight();

        widgetHeight += marginTop + marginBottom + bgPadding * 2;
        // Grow the box by the horizontal margins, mirroring widgetHeight above. Text was already
        // wrapped at the pre-margin width, so the margins become empty space on either side.
        widgetWidth += marginLeft + marginRight;

        // A bottom-anchored overlay is positioned from the height it reported on the *previous*
        // frame, so a height change reaches the placement a frame late. Painting the new height
        // into the old placement lifts every line by a row for that one frame, which is what makes
        // a message look like it turns into the one below it just as it finishes fading out. Paint
        // into the height we were actually given and let the new height take effect next frame,
        // once the placement agrees with it. Player-following widgets position themselves below,
        // from the live height, so they are unaffected.
        int layoutHeight = (!followPlayer && lastReportedHeight > 0) ? lastReportedHeight : widgetHeight;
        lastReportedHeight = followPlayer ? 0 : widgetHeight;

        if (followPlayer) {
            Player localPlayer = client.getLocalPlayer();
            if (localPlayer != null) {
                Point playerPoint;
                if (positionMode == WidgetPosition.BELOW_PLAYER) {
                    playerPoint = localPlayer.getCanvasTextLocation(graphics, "", 0);
                } else {
                    playerPoint = localPlayer.getCanvasTextLocation(graphics, "", localPlayer.getLogicalHeight());
                }
                if (playerPoint != null) {
                    int zoomOffset = calculateZoomOffset(positionMode);
                    int x = playerPoint.getX() - widgetWidth / 2;
                    int y = playerPoint.getY() + zoomOffset - layoutHeight / 2;
                    graphics.translate(x - getBounds().x, y - getBounds().y);
                }
            }
        }

        Shape originalClip = graphics.getClip();
        graphics.setClip(0, 0, widgetWidth, layoutHeight + 4);

        if (background.getAlpha() > 0) {
            graphics.setColor(background);
            graphics.fillRect(0, 0, widgetWidth, layoutHeight);
        }

        int y = layoutHeight - bgPadding - marginBottom - metrics.getDescent();

        if (inputSegments != null) {
            drawSegments(graphics, inputSegments, 255, y, followPlayer, widgetWidth, bgPadding,
                    marginLeft, marginRight, fontSize, metrics, modIcons, drawShadow);
            y -= lineHeight;
        }

        for (int i = renderableLines.size() - 1; i >= 0; i--) {
            RenderLine line = renderableLines.get(i);
            if (line.alpha <= 0) {
                continue;
            }
            drawSegments(graphics, line.segments, line.alpha, y, followPlayer, widgetWidth, bgPadding,
                    marginLeft, marginRight, fontSize, metrics, modIcons, drawShadow);
            y -= lineHeight;
        }

        graphics.setClip(originalClip);

        if (followPlayer) {
            return null;
        }
        return new Dimension(widgetWidth, widgetHeight);
    }

    private boolean shouldRender() {
        if (!overlayConfig.isShow()) {
            return false;
        }
        if (client.getGameState() != GameState.LOGGED_IN) {
            return false;
        }
        if (overlayConfig.isAlwaysVisible()) {
            return true;
        }
        return plugin.isChatboxHidden();
    }

    private int calculateZoomOffset(WidgetPosition positionMode) {
        int zoom = client.get3dZoom();
        double normalizedZoom = (double) (zoom - MIN_ZOOM) / (MAX_ZOOM - MIN_ZOOM);
        normalizedZoom = Math.max(0, Math.min(1, normalizedZoom));

        int minOffset, maxOffset;
        if (positionMode == WidgetPosition.BELOW_PLAYER) {
            minOffset = BELOW_OFFSET_MIN_ZOOM;
            maxOffset = BELOW_OFFSET_MAX_ZOOM;
        } else {
            minOffset = ABOVE_OFFSET_MIN_ZOOM;
            maxOffset = ABOVE_OFFSET_MAX_ZOOM;
        }

        return (int) (minOffset + normalizedZoom * (maxOffset - minOffset));
    }

    private Color getCategoryColour(ChatMessageType type) {
        if (type == ChatMessageType.DIDYOUKNOW) {
            return globalConfig.didYouKnowColour();
        }
        if (type == ChatMessageType.BROADCAST) {
            return globalConfig.broadcastColour();
        }

        switch (MessageCategory.fromType(type)) {
            case GAME:
            case GAME_CLAN:
                return globalConfig.gameColour();
            case TRADE:
                return globalConfig.tradeColour();
            case CHALLENGE:
                return globalConfig.challengeColour();
            case PUBLIC_CHAT:
                return globalConfig.publicColour();
            case AUTO:
                return globalConfig.autoColour();
            case FRIENDS_CHAT:
                return globalConfig.friendsColour();
            case CLAN_CHAT:
                return globalConfig.clanColour();
            case GUEST_CLAN_CHAT:
                return globalConfig.guestClanColour();
            case GIM_CLAN_CHAT:
                return globalConfig.gimClanColour();
            case PRIVATE:
                return globalConfig.privateColour();
            default:
                return globalConfig.gameColour();
        }
    }

    private int calculateLineWidth(List<TextSegment> segments, FontMetrics metrics) {
        int width = 0;
        for (TextSegment segment : segments) {
            if (segment.iconId >= 0) {
                width += segment.width;
            } else {
                width += metrics.stringWidth(segment.text);
            }
        }
        return width;
    }

    private void drawSegments(Graphics2D graphics, List<TextSegment> segments, int alpha, int y,
            boolean followPlayer, int widgetWidth, int xPad, int marginLeft, int marginRight,
            FontSize fontSize, FontMetrics metrics, IndexedSprite[] modIcons, boolean drawShadow) {
        int lineWidth = calculateLineWidth(segments, metrics);
        // Left-anchor at the left margin, or centre within the content region (box minus both
        // margins) when following the player — mirroring how marginBottom offsets the baseline.
        int x = followPlayer
                ? marginLeft + xPad + (widgetWidth - marginLeft - marginRight - xPad * 2 - lineWidth) / 2
                : xPad + marginLeft;
        for (TextSegment segment : segments) {
            if (segment.iconId >= 0) {
                BufferedImage img = ChatRenderUtils.getModIconImage(segment.iconId, modIcons);
                if (img != null) {
                    x += ChatRenderUtils.drawIcon(graphics, img, fontSize, metrics, x, y);
                } else {
                    x += segment.width;
                }
            } else {
                Color segmentColor = segment.color != null ? segment.color : Color.WHITE;
                x += ChatRenderUtils.drawText(graphics, segment, segmentColor, alpha, x, y,
                        drawShadow, metrics);
            }
        }
    }

    /**
     * Builds the live "input preview" line for the bottom of the widget when this widget has it
     * enabled: the game's own input line (icon + name + typed text + {@code *} / "Press Enter to
     * Chat..."), with the name white and only an actively-typed message in the configured Public
     * colour. Returns {@code null} when disabled or there is nothing to show.
     */
    private List<TextSegment> buildInputPreviewSegments(FontMetrics metrics, FontSize fontSize,
            IndexedSprite[] modIcons) {
        // render() already returned early unless shouldRender() (which requires LOGGED_IN).
        if (!overlayConfig.isShowInputPreview()) {
            return null;
        }
        String typed = client.getVarcStrValue(VarClientID.CHATINPUT);
        String text = resolveInputText(typed);
        if (text == null || text.isEmpty()) {
            return null;
        }

        boolean hasTyped = typed != null && !typed.isEmpty();
        // When this widget only wants the preview while typing, suppress the idle "Press Enter to
        // Chat..." prompt: show nothing until the first character is typed.
        if (overlayConfig.isPreviewOnlyWhenTyping() && !hasTyped) {
            return null;
        }
        Color nameColor = Color.WHITE;
        Color messageColor = hasTyped ? globalConfig.publicColour() : Color.WHITE;

        List<TextSegment> segments = new ArrayList<>();
        int colonIdx = text.indexOf(':');
        if (colonIdx >= 0) {
            segments.addAll(ChatRenderUtils.parseTextWithColoursAndIcons(
                    text.substring(0, colonIdx + 1), metrics, modIcons, false, nameColor, fontSize, chatColorConfig));
            segments.addAll(ChatRenderUtils.parseTextWithColoursAndIcons(
                    text.substring(colonIdx + 1), metrics, modIcons, false, messageColor, fontSize, chatColorConfig));
        } else {
            segments.addAll(ChatRenderUtils.parseTextWithColoursAndIcons(
                    text, metrics, modIcons, false, messageColor, fontSize, chatColorConfig));
        }
        return segments;
    }

    /** The game's formatted chat input line, or a reconstructed fallback if the widget is null. */
    private String resolveInputText(String typed) {
        Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
        if (input != null) {
            String text = input.getText();
            if (text != null && !text.isEmpty()) {
                return text;
            }
        }
        Player local = client.getLocalPlayer();
        if (local == null || local.getName() == null) {
            return null;
        }
        // The raw varc holds what the player typed, unescaped: escape it so a typed '<' isn't
        // parsed as a formatting tag.
        return local.getName() + ": " + (typed != null ? Text.escapeJagex(typed) : "") + "*";
    }
}

package com.chatwidgets.overlay;

import com.chatwidgets.model.FontSize;
import com.chatwidgets.model.MessageCategory;
import com.chatwidgets.model.WidgetPosition;
import net.runelite.api.ChatMessageType;

import java.awt.Color;
import java.util.EnumSet;
import java.util.Set;
import java.util.UUID;

/**
 * Per-overlay configuration POJO. Each instance defines a single chat widget's behaviour:
 * which message types it shows, its position mode, fade duration, max visible messages, etc.
 *
 * <p>Serialized to/from JSON via Gson and stored as a single config key in RuneLite's
 * {@link net.runelite.client.config.ConfigManager}. On first run, two defaults are created
 * via {@link #defaultAllWidget()} and {@link #defaultPrivateWidget()}.
 */
public class OverlayConfig {
    /** Fully-transparent background — the "no background" / disabled state. */
    private static final Color TRANSPARENT = new Color(0, 0, 0, 0);

    private String id;
    private String name;
    private Set<ChatMessageType> messageTypes;
    private int maxMessages;
    private int fadeOutDuration;
    private int widgetWidth;
    private int marginTop;
    private int marginBottom;
    private int marginLeft;
    private int marginRight;
    private boolean dynamicHeight;
    private boolean hideDuplicateCount;
    private boolean contextualColours;
    private boolean showTimestamp;
    private boolean showInputPreview;
    private boolean previewOnlyWhenTyping;
    private boolean show;
    private boolean alwaysVisible;
    private FontSize fontSize;
    private Color backgroundColour;
    private WidgetPosition position;

    public OverlayConfig() {
        this.id = UUID.randomUUID().toString();
        this.name = "New Widget";
        this.messageTypes = EnumSet.noneOf(ChatMessageType.class);
        this.maxMessages = 10;
        this.fadeOutDuration = 0;
        this.widgetWidth = 512;
        this.marginTop = 0;
        this.marginBottom = 0;
        this.marginLeft = 0;
        this.marginRight = 0;
        this.dynamicHeight = false;
        this.hideDuplicateCount = false;
        this.contextualColours = true;
        this.showTimestamp = false;
        this.showInputPreview = false;
        this.previewOnlyWhenTyping = false;
        this.show = true;
        this.alwaysVisible = false;
        this.fontSize = FontSize.REGULAR;
        this.backgroundColour = TRANSPARENT;
        this.position = WidgetPosition.WIDGET;
    }

    public static OverlayConfig createDefault(String name, Set<ChatMessageType> types, boolean alwaysVisible) {
        OverlayConfig config = new OverlayConfig();
        config.name = name;
        config.messageTypes = EnumSet.copyOf(types);
        config.alwaysVisible = alwaysVisible;
        return config;
    }

    public static OverlayConfig defaultAllWidget() {
        EnumSet<ChatMessageType> types = EnumSet.noneOf(ChatMessageType.class);
        for (MessageCategory category : MessageCategory.values()) {
            if (category != MessageCategory.PRIVATE) {
                types.addAll(category.getTypes());
            }
        }
        OverlayConfig config = createDefault("All Messages", types, false);
        config.showInputPreview = true;
        return config;
    }

    public static OverlayConfig defaultPrivateWidget() {
        EnumSet<ChatMessageType> types = EnumSet.noneOf(ChatMessageType.class);
        types.addAll(MessageCategory.PRIVATE.getTypes());
        OverlayConfig config = createDefault("Private Messages", types, true);
        config.contextualColours = false;
        return config;
    }

    // Getters and setters

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public Set<ChatMessageType> getMessageTypes() {
        return messageTypes;
    }

    public void setMessageTypes(Set<ChatMessageType> messageTypes) {
        this.messageTypes = messageTypes;
    }

    public int getMaxMessages() {
        return maxMessages;
    }

    public void setMaxMessages(int maxMessages) {
        this.maxMessages = Math.max(1, Math.min(20, maxMessages));
    }

    public int getFadeOutDuration() {
        return fadeOutDuration;
    }

    public void setFadeOutDuration(int fadeOutDuration) {
        this.fadeOutDuration = Math.max(0, Math.min(300, fadeOutDuration));
    }

    public int getWidgetWidth() {
        return widgetWidth;
    }

    public void setWidgetWidth(int widgetWidth) {
        this.widgetWidth = Math.max(150, Math.min(1024, widgetWidth));
    }

    public int getMarginTop() {
        return marginTop;
    }

    public void setMarginTop(int marginTop) {
        this.marginTop = Math.max(0, Math.min(200, marginTop));
    }

    public int getMarginBottom() {
        return marginBottom;
    }

    public void setMarginBottom(int marginBottom) {
        this.marginBottom = Math.max(0, Math.min(200, marginBottom));
    }

    public int getMarginLeft() {
        return marginLeft;
    }

    public void setMarginLeft(int marginLeft) {
        this.marginLeft = Math.max(0, Math.min(200, marginLeft));
    }

    public int getMarginRight() {
        return marginRight;
    }

    public void setMarginRight(int marginRight) {
        this.marginRight = Math.max(0, Math.min(200, marginRight));
    }

    public boolean isDynamicHeight() {
        return dynamicHeight;
    }

    public void setDynamicHeight(boolean dynamicHeight) {
        this.dynamicHeight = dynamicHeight;
    }

    public boolean isHideDuplicateCount() {
        return hideDuplicateCount;
    }

    public void setHideDuplicateCount(boolean hideDuplicateCount) {
        this.hideDuplicateCount = hideDuplicateCount;
    }

    public boolean isContextualColours() {
        return contextualColours;
    }

    public void setContextualColours(boolean contextualColours) {
        this.contextualColours = contextualColours;
    }

    public boolean isShowTimestamp() {
        return showTimestamp;
    }

    public void setShowTimestamp(boolean showTimestamp) {
        this.showTimestamp = showTimestamp;
    }

    public boolean isShowInputPreview() {
        return showInputPreview;
    }

    public void setShowInputPreview(boolean showInputPreview) {
        this.showInputPreview = showInputPreview;
    }

    public boolean isPreviewOnlyWhenTyping() {
        return previewOnlyWhenTyping;
    }

    public void setPreviewOnlyWhenTyping(boolean previewOnlyWhenTyping) {
        this.previewOnlyWhenTyping = previewOnlyWhenTyping;
    }

    public FontSize getFontSize() {
        // Widgets serialized before this field existed deserialize fontSize as null.
        return fontSize != null ? fontSize : FontSize.REGULAR;
    }

    public void setFontSize(FontSize fontSize) {
        this.fontSize = fontSize;
    }

    public Color getBackgroundColour() {
        // Widgets serialized before this field existed deserialize backgroundColour as null.
        return backgroundColour != null ? backgroundColour : TRANSPARENT;
    }

    public void setBackgroundColour(Color backgroundColour) {
        this.backgroundColour = backgroundColour;
    }

    public boolean isShow() {
        return show;
    }

    public void setShow(boolean show) {
        this.show = show;
    }

    public boolean isAlwaysVisible() {
        return alwaysVisible;
    }

    public void setAlwaysVisible(boolean alwaysVisible) {
        this.alwaysVisible = alwaysVisible;
    }

    public WidgetPosition getPosition() {
        return position;
    }

    public void setPosition(WidgetPosition position) {
        this.position = position;
    }
}

