package com.chatwidgets.overlay;

import java.awt.Color;

/**
 * A single renderable piece of a message line — either a text string with a colour, an icon
 * reference (identified by {@code iconId} into the client's modIcons array), or a line break
 * sentinel ({@link #LINE_BREAK}).
 *
 * <p>Text segments may also carry the in-game font decorations: a strikethrough colour
 * ({@code <str>}), an underline colour ({@code <u>}) and a shadow colour ({@code <shad>}). A null
 * strike or underline colour means none; a null shadow colour means the base shadow, which the
 * renderer resolves from config.
 */
public class TextSegment {
    public static final int LINE_BREAK = -2;

    public final String text;
    public final int iconId;
    public final int width;
    public final Color color;
    public final Color strikeColor;
    public final Color underlineColor;
    public final Color shadowColor;

    public TextSegment(String text, int iconId, int width, Color color) {
        this(text, iconId, width, color, null, null, null);
    }

    public TextSegment(String text, int iconId, int width, Color color,
            Color strikeColor, Color underlineColor, Color shadowColor) {
        this.text = text;
        this.iconId = iconId;
        this.width = width;
        this.color = color;
        this.strikeColor = strikeColor;
        this.underlineColor = underlineColor;
        this.shadowColor = shadowColor;
    }

    /** A copy of this segment's formatting applied to different text (used when wrapping). */
    public TextSegment withText(String newText, int newWidth) {
        return new TextSegment(newText, iconId, newWidth, color, strikeColor, underlineColor, shadowColor);
    }
}

package com.chatwidgets;

import com.chatwidgets.model.MessageVariant;
import net.runelite.api.ChatMessageType;
import org.junit.Test;

import java.util.function.IntFunction;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for {@link ChatPipeParser}, which mirrors the chatbox cs2's per-type {@code |}
 * handling ({@code rebuildchatbox}, {@code script632}, {@code chat_broadcast_parseurl}).
 */
public class ChatPipeParserTest {

    private static final String NEWS_URL = "https://secure.runescape.com/m=news/";

    /** Stand-in for {@code enum_63}: key 0 resolves, key 5 maps to an empty URL, the rest are unset. */
    private static final IntFunction<String> URLS = key -> {
        if (key == 0) {
            return NEWS_URL;
        }
        if (key == 5) {
            return "";
        }
        return null;
    };

    private static ChatPipeParser.Result parse(ChatMessageType type, String raw) {
        return ChatPipeParser.parse(type, raw, false, URLS);
    }

    private static void assertResult(ChatPipeParser.Result r, String text, MessageVariant variant,
            Integer taskId, String url) {
        assertEquals("text", text, r.getText());
        assertEquals("variant", variant, r.getVariant());
        assertEquals("achievementTaskId", taskId, r.getAchievementTaskId());
        assertEquals("broadcastUrl", url, r.getBroadcastUrl());
    }

    // --- GAMEMESSAGE ---

    @Test
    public void gameMessageCombatAchievementShowsRightAndKeepsTaskId() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "CA_ID:565|Congratulations, you've completed a task."),
                "Congratulations, you've completed a task.", MessageVariant.NORMAL, 565, null);
    }

    @Test
    public void gameMessageWithoutPipeIsUntouched() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "Welcome to Old School RuneScape."),
                "Welcome to Old School RuneScape.", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageLeadingPipeShowsRemainder() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "|hello"), "hello", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageTrailingPipeLeavesBlankText() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "a|"), "", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageSplitsAtFirstPipeOnly() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "a|b|c"), "b|c", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageNonNumericTaskIdIsNullButTextStillSplit() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "CA_ID:abc|Done."), "Done.", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageNonCaLeftPartIsDiscarded() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "something|Shown."), "Shown.", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageCaIdFoundAnywhereInLeftPart() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "xCA_ID:12|Shown."), "Shown.", MessageVariant.NORMAL, 12, null);
    }

    @Test
    public void gameMessagePluginTextIsMirroredLikeTheChatbox() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "a | b"), " b", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gameMessageBlankAfterSplit() {
        assertResult(parse(ChatMessageType.GAMEMESSAGE, "CA_ID:1|"), "", MessageVariant.NORMAL, 1, null);
    }

    // --- CLAN_MESSAGE ---

    @Test
    public void clanMessagePvpArenaForm() {
        assertResult(parse(ChatMessageType.CLAN_MESSAGE, "p|PvP Arena test"),
                "PvP Arena test", MessageVariant.PVP_ARENA, null, null);
    }

    @Test
    public void clanMessagePvpArenaSplitsOnceOnly() {
        assertResult(parse(ChatMessageType.CLAN_MESSAGE, "p|a|b"), "a|b", MessageVariant.PVP_ARENA, null, null);
    }

    @Test
    public void clanMessageGimFormWithTaskId() {
        assertResult(parse(ChatMessageType.CLAN_MESSAGE, "|CA_ID:7|Group task."),
                "Group task.", MessageVariant.GIM, 7, null);
    }

    @Test
    public void clanMessageGimFormPlain() {
        assertResult(parse(ChatMessageType.CLAN_MESSAGE, "|Group note."), "Group note.", MessageVariant.GIM, null, null);
    }

    @Test
    public void clanMessageNormalWithTaskId() {
        assertResult(parse(ChatMessageType.CLAN_MESSAGE, "CA_ID:565|Bob completed a task."),
                "Bob completed a task.", MessageVariant.NORMAL, 565, null);
    }

    @Test
    public void clanMessageNormalWithoutPipe() {
        assertResult(parse(ChatMessageType.CLAN_MESSAGE, "Bob has joined."), "Bob has joined.",
                MessageVariant.NORMAL, null, null);
    }

    // --- GIM types ---

    @Test
    public void clanGimMessageStripsLeadingPipeThenSplitsAgain() {
        assertResult(parse(ChatMessageType.CLAN_GIM_MESSAGE, "|CA_ID:1|GIM test"),
                "GIM test", MessageVariant.GIM, 1, null);
    }

    @Test
    public void clanGimMessagePlain() {
        assertResult(parse(ChatMessageType.CLAN_GIM_MESSAGE, "|Bob has logged in."),
                "Bob has logged in.", MessageVariant.GIM, null, null);
    }

    /** RuneLite's event message: retyped to CLAN_GIM_MESSAGE with the leading | already stripped. */
    @Test
    public void clanGimMessageEventFormWithTaskId() {
        assertResult(ChatPipeParser.parseEvent(ChatMessageType.CLAN_GIM_MESSAGE, "CA_ID:1|GIM test", true, URLS),
                "GIM test", MessageVariant.GIM, 1, null);
    }

    @Test
    public void clanGimMessageEventFormPlain() {
        assertResult(ChatPipeParser.parseEvent(ChatMessageType.CLAN_GIM_MESSAGE, "Bob has logged in.", true, URLS),
                "Bob has logged in.", MessageVariant.GIM, null, null);
    }

    /** RuneLite's event message: retyped to CLAN_GIM_CHAT with the leading | already stripped. */
    @Test
    public void clanGimChatEventFormUntouched() {
        assertResult(ChatPipeParser.parseEvent(ChatMessageType.CLAN_GIM_CHAT, "hi all", true, URLS),
                "hi all", MessageVariant.GIM, null, null);
    }

    @Test
    public void clanGimChatStripsLeadingPipe() {
        assertResult(ChatPipeParser.parse(ChatMessageType.CLAN_GIM_CHAT, "|hi all", true, URLS),
                "hi all", MessageVariant.GIM, null, null);
    }

    @Test
    public void clanGimChatKeepsLaterPipes() {
        assertResult(ChatPipeParser.parse(ChatMessageType.CLAN_GIM_CHAT, "|a|b", true, URLS),
                "a|b", MessageVariant.GIM, null, null);
    }

    @Test
    public void gimEventKeepsLiteralLeadingPipe() {
        assertResult(ChatPipeParser.parseEvent(ChatMessageType.CLAN_GIM_CHAT, "|a|b", true, URLS),
                "|a|b", MessageVariant.GIM, null, null);
        assertResult(ChatPipeParser.parse(ChatMessageType.CLAN_GIM_CHAT, "||a|b", true, URLS),
                "|a|b", MessageVariant.GIM, null, null);
    }

    @Test
    public void gimEventOutsideGroupRestoresTransportPipe() {
        assertResult(ChatPipeParser.parseEvent(ChatMessageType.CLAN_GIM_CHAT, "hello", false, URLS),
                "|hello", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gimNodeOutsideGroupKeepsTransportPipe() {
        assertResult(parse(ChatMessageType.CLAN_GIM_CHAT, "|hello"),
                "|hello", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void gimEventAndNodeNotificationFormsAgree() {
        assertResult(ChatPipeParser.parseEvent(ChatMessageType.CLAN_GIM_MESSAGE, "|note", false, URLS),
                "note", MessageVariant.GIM, null, null);
        assertResult(parse(ChatMessageType.CLAN_GIM_MESSAGE, "||note"),
                "note", MessageVariant.GIM, null, null);
    }

    @Test
    public void clanChatLeadingPipeStrippedWhenInGim() {
        assertResult(ChatPipeParser.parse(ChatMessageType.CLAN_CHAT, "|hi", true, URLS),
                "hi", MessageVariant.GIM, null, null);
    }

    @Test
    public void clanChatLeadingPipeUntouchedWhenNotInGim() {
        assertResult(parse(ChatMessageType.CLAN_CHAT, "|hi"), "|hi", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void clanChatWithoutLeadingPipeUntouchedEvenInGim() {
        assertResult(ChatPipeParser.parse(ChatMessageType.CLAN_CHAT, "a|b", true, URLS),
                "a|b", MessageVariant.NORMAL, null, null);
    }

    // --- BROADCAST ---

    @Test
    public void broadcastWithValidKeyKeepsLeftAndAddsIcon() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news|0"),
                "<img=12> Test news", MessageVariant.NORMAL, null, NEWS_URL);
    }

    @Test
    public void broadcastWithBadKeyCharKeepsLeftWithoutIcon() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news|!"), "Test news", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void broadcastWithUppercaseKeyIsNotBase36() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news|A"), "Test news", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void broadcastWithEmptyUrlKeepsLeftWithoutIcon() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news|5"), "Test news", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void broadcastWithUnsetKeyKeepsLeftWithoutIcon() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news|z"), "Test news", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void broadcastWithoutPipeIsUntouched() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news"), "Test news", MessageVariant.NORMAL, null, null);
    }

    @Test
    public void broadcastWithTrailingPipeKeepsLeftWithoutIcon() {
        assertResult(parse(ChatMessageType.BROADCAST, "Test news|"), "Test news", MessageVariant.NORMAL, null, null);
    }

    // --- Untouched types ---

    @Test
    public void playerChatTypesContainingPipeAreUntouched() {
        ChatMessageType[] types = {
                ChatMessageType.PUBLICCHAT, ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT,
                ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.MODCHAT
        };
        for (ChatMessageType type : types) {
            assertResult(ChatPipeParser.parse(type, "|a|b", true, URLS), "|a|b", MessageVariant.NORMAL, null, null);
        }
    }

    @Test
    public void otherGameTypesAreUntouched() {
        assertResult(parse(ChatMessageType.SPAM, "CA_ID:1|x"), "CA_ID:1|x", MessageVariant.NORMAL, null, null);
        assertResult(parse(ChatMessageType.CLAN_GUEST_MESSAGE, "p|x"), "p|x", MessageVariant.NORMAL, null, null);
    }
}

package com.chatwidgets;

import com.chatwidgets.model.MessageVariant;
import com.chatwidgets.model.WidgetMessage;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.PluginManager;
import org.junit.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.*;

/** Exercises the combined pipe/macro pipeline through capture and delayed rewrites. */
public class ChatWidgetPipelineTest {
    private final AtomicBoolean inGim = new AtomicBoolean(true);

    private static <T> T proxy(Class<T> type, InvocationHandler handler) {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
    }

    private ChatWidgetPlugin plugin() throws Exception {
        ClanSettings settings = proxy(ClanSettings.class, (p, m, a) -> null);
        ClanChannel channel = proxy(ClanChannel.class, (p, m, a) -> null);
        Client client = proxy(Client.class, (p, m, a) -> {
            switch (m.getName()) {
                case "macroExpand":
                    return ((String) a[0]).replace("@red@", "<col=ff0000>");
                case "getClanSettings":
                    return inGim.get() ? settings : null;
                case "getClanChannel":
                    return inGim.get() ? channel : null;
                default:
                    return null;
            }
        });
        // An empty real manager makes Emojis disabled, exercising the event capture path.
        Constructor<?> constructor = PluginManager.class.getDeclaredConstructors()[0];
        constructor.setAccessible(true);
        PluginManager manager = (PluginManager) constructor.newInstance(
                false, false, new EventBus(), null, null, null, null);
        ChatWidgetPlugin plugin = new ChatWidgetPlugin();
        set(plugin, "client", client);
        set(plugin, "config", new ChatWidgetConfig() {});
        set(plugin, "pluginManager", manager);
        return plugin;
    }

    private static void set(ChatWidgetPlugin plugin, String name, Object value) throws Exception {
        Field field = ChatWidgetPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }

    @SuppressWarnings("unchecked")
    private static List<WidgetMessage> pool(ChatWidgetPlugin plugin) throws Exception {
        Field field = ChatWidgetPlugin.class.getDeclaredField("messages");
        field.setAccessible(true);
        return (List<WidgetMessage>) field.get(plugin);
    }

    private static void rewrite(ChatWidgetPlugin plugin, WidgetMessage old, String body,
            boolean eventText) throws Exception {
        Method method = ChatWidgetPlugin.class.getDeclaredMethod(
                "rebuildPooledMessage", WidgetMessage.class, String.class, boolean.class);
        method.setAccessible(true);
        method.invoke(plugin, old, body, eventText);
    }

    @Test
    public void captureKeepsLiteralPipeInGimEvent() throws Exception {
        ChatWidgetPlugin plugin = plugin();
        plugin.onChatMessage(new ChatMessage(null, ChatMessageType.CLAN_GIM_CHAT,
                "Alice", "|a|b", "Group", 0));
        assertEquals("|a|b", pool(plugin).get(0).getMessage());
        assertEquals(MessageVariant.GIM, pool(plugin).get(0).getVariant());
    }

    @Test
    public void captureOutsideGimRestoresPipe() throws Exception {
        inGim.set(false);
        ChatWidgetPlugin plugin = plugin();
        plugin.onChatMessage(new ChatMessage(null, ChatMessageType.CLAN_GIM_CHAT,
                "Alice", "hello", "Group", 0));
        assertEquals("|hello", pool(plugin).get(0).getMessage());
        assertEquals(MessageVariant.NORMAL, pool(plugin).get(0).getVariant());
    }

    @Test
    public void captureSplitsPayloadBeforeExpandingMacros() throws Exception {
        ChatWidgetPlugin plugin = plugin();
        plugin.onChatMessage(new ChatMessage(null, ChatMessageType.GAMEMESSAGE,
                "", "CA_ID:565|@red@Done", null, 0));
        WidgetMessage message = pool(plugin).get(0);
        assertEquals("<col=ff0000>Done", message.getMessage());
        assertEquals(Integer.valueOf(565), message.getAchievementTaskId());
    }

    @Test
    public void nodeRewriteKeepsMembershipSnapshotMacrosAndMetadata() throws Exception {
        ChatWidgetPlugin plugin = plugin();
        WidgetMessage old = WidgetMessage.senderMessage("Alice", "Group", "old", 123,
                ChatMessageType.CLAN_GIM_CHAT, false, MessageVariant.GIM);
        old.setCount(3);
        pool(plugin).add(old);
        inGim.set(false);
        rewrite(plugin, old, "||a|b @red@new<img=10>", false);
        WidgetMessage updated = pool(plugin).get(0);
        assertEquals("|a|b <col=ff0000>new<img=10>", updated.getMessage());
        assertEquals(MessageVariant.GIM, updated.getVariant());
        assertEquals("Group", updated.getChannelName());
        assertEquals(123, updated.getTimestamp());
        assertEquals(3, updated.getCount());
    }

    @Test
    public void nodeRewriteOutsideGimKeepsPipeAfterJoiningGroup() throws Exception {
        ChatWidgetPlugin plugin = plugin();
        WidgetMessage old = WidgetMessage.senderMessage("Alice", "Group", "|old", 123,
                ChatMessageType.CLAN_GIM_CHAT, false, MessageVariant.NORMAL);
        pool(plugin).add(old);
        rewrite(plugin, old, "|new<img=10>", false);
        assertEquals("|new<img=10>", pool(plugin).get(0).getMessage());
        assertEquals(MessageVariant.NORMAL, pool(plugin).get(0).getVariant());
    }

    @Test
    public void delayedGimCommandResultUsesEventText() throws Exception {
        ChatWidgetPlugin plugin = plugin();
        AtomicReference<String> result = new AtomicReference<>();
        MessageNode node = proxy(MessageNode.class,
                (p, m, a) -> m.getName().equals("getRuneLiteFormatMessage") ? result.get() : null);
        plugin.onChatMessage(new ChatMessage(node, ChatMessageType.CLAN_GIM_CHAT,
                "Alice", "!test", "Group", 0));
        result.set("|literal @red@result");
        plugin.onGameTick(new GameTick());
        assertEquals("|literal <col=ff0000>result", pool(plugin).get(0).getMessage());
    }

    @Test
    public void blankPayloadRewriteDropsMessage() throws Exception {
        ChatWidgetPlugin plugin = plugin();
        WidgetMessage old = WidgetMessage.gameMessage("old", 123, ChatMessageType.GAMEMESSAGE, false);
        pool(plugin).add(old);
        rewrite(plugin, old, "CA_ID:1|", false);
        assertTrue(pool(plugin).isEmpty());
    }
}

