package com.chatwidgets.dev;

import net.runelite.api.ChatMessageType;
import net.runelite.client.ui.ColorScheme;

import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;

/**
 * Debug section content for {@link DevMessagesPlugin}, shown inside the Chat Widgets sidebar.
 * Picking a preset copies its type, name, sender and text into the fields below so they can be
 * edited before sending. A plain panel rather than a {@code Config}, because RuneLite's config
 * panel does not redraw when a value is set from code.
 */
class DevMessagesPanel extends JPanel {

    /** Receives a message to send; called on the Swing thread. */
    interface Sender {
        void send(ChatMessageType type, String name, String message, String sender);
    }

    private final JComboBox<DevMessagePreset> presetBox = new JComboBox<>(DevMessagePreset.values());
    private final JComboBox<ChatMessageType> typeBox = new JComboBox<>(ChatMessageType.values());
    private final JTextField nameField = new JTextField();
    private final JTextField senderField = new JTextField();
    private final JTextArea messageArea = new JTextArea(8, 20);

    DevMessagesPanel(Sender sender) {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);

        messageArea.setLineWrap(true);
        messageArea.setWrapStyleWord(true);

        presetBox.addActionListener(e -> loadPreset((DevMessagePreset) presetBox.getSelectedItem()));

        JButton sendButton = new JButton("Send");
        sendButton.addActionListener(e -> sender.send((ChatMessageType) typeBox.getSelectedItem(),
                nameField.getText(), messageArea.getText(), senderField.getText()));

        JButton sendAllButton = new JButton("Send all presets");
        sendAllButton.addActionListener(e -> {
            for (DevMessagePreset p : DevMessagePreset.values()) {
                sender.send(p.type, p.playerName, p.message, p.sender);
            }
        });

        add(labelled("Preset", presetBox));
        add(labelled("Type", typeBox));
        add(labelled("Name (player chat)", nameField));
        add(labelled("Sender (channel name)", senderField));
        // RuneLite's LAF gives scroll panes an empty border, so outline the box against the section
        JScrollPane messageScroll = new JScrollPane(messageArea);
        messageScroll.setBorder(new LineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        add(labelled("Message", messageScroll));

        JPanel buttons = new JPanel(new GridLayout(2, 1, 0, 4));
        buttons.setOpaque(false);
        buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
        buttons.add(sendButton);
        buttons.add(sendAllButton);
        fillWidth(buttons);
        add(buttons);

        loadPreset((DevMessagePreset) presetBox.getSelectedItem());
    }

    private void loadPreset(DevMessagePreset preset) {
        if (preset == null) {
            return;
        }
        typeBox.setSelectedItem(preset.type);
        nameField.setText(preset.playerName);
        senderField.setText(preset.sender);
        messageArea.setText(preset.message);
        messageArea.setCaretPosition(0);
    }

    private static JPanel labelled(String label, Component field) {
        JPanel row = new JPanel(new BorderLayout(0, 2));
        row.setOpaque(false);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setBorder(new EmptyBorder(0, 0, 4, 0));
        row.add(new JLabel(label), BorderLayout.NORTH);
        row.add(field, BorderLayout.CENTER);
        fillWidth(field);
        fillWidth(row);
        return row;
    }

    /**
     * Drops the preferred width so the component fills the sidebar instead of widening it; long
     * enum names and the text area's column count would otherwise overflow to the right.
     */
    private static void fillWidth(Component c) {
        int height = c.getPreferredSize().height;
        c.setPreferredSize(new Dimension(0, height));
        c.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
    }
}

package com.chatwidgets.dev;

import com.chatwidgets.ChatWidgetPlugin;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

import javax.inject.Inject;

/**
 * Dev-only plugin that injects test chat messages via {@link Client#addChatMessage}, so they flow
 * through a real {@code ChatMessage} event and render in both the native chatbox and our widgets.
 * Its UI is a Debug section in the Chat Widgets sidebar. Lives under src/test so the Plugin Hub
 * build never ships it; loaded by {@code ChatWidgetPluginTest}.
 */
@PluginDescriptor(name = "Chat Widgets Dev Messages", description = "Inject test chat messages for Chat Widgets", developerPlugin = true)
public class DevMessagesPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private PluginManager pluginManager;

    @Override
    protected void startUp() {
        setDebugSection(new DevMessagesPanel(this::send));
    }

    @Override
    protected void shutDown() {
        setDebugSection(null);
    }

    // Looked up rather than injected: @PluginDependency only works for plugins that expose Guice
    // services. ChatWidgetPlugin keeps the section if it starts after us or restarts.
    private void setDebugSection(DevMessagesPanel section) {
        for (Plugin plugin : pluginManager.getPlugins()) {
            if (plugin instanceof ChatWidgetPlugin) {
                ((ChatWidgetPlugin) plugin).setDebugSection(section);
            }
        }
    }

    private void send(ChatMessageType type, String name, String message, String sender) {
        clientThread.invoke(() -> {
            if (client.getGameState() != GameState.LOGGED_IN || message.isEmpty()) {
                return;
            }
            client.addChatMessage(type, name, message, sender.isEmpty() ? null : sender);
        });
    }
}

package com.chatwidgets.overlay;

import com.chatwidgets.model.FontSize;
import org.junit.BeforeClass;
import org.junit.Test;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

import static org.junit.Assert.assertEquals;

/**
 * Covers the {@code <at>} escape decode in {@link ChatRenderUtils}. RuneLite escapes a literal
 * {@code @} as {@code <at>} in message text (so it isn't parsed as an {@code @col@} colour code);
 * both parsers must turn it back into {@code @}, alongside the existing {@code <lt>} / {@code <gt>}
 * decoding. The helper needs only a headless {@link FontMetrics}; no injected RuneLite services.
 */
public class AtEscapeTest {

    private static FontMetrics metrics;

    @BeforeClass
    public static void setUp() {
        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        metrics = g.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        g.dispose();
    }

    /** Concatenates the text of every non-icon, non-break segment. */
    private static String textOf(List<TextSegment> segments) {
        StringBuilder sb = new StringBuilder();
        for (TextSegment s : segments) {
            if (s.iconId == -1) {
                sb.append(s.text);
            }
        }
        return sb.toString();
    }

    private static String renderBody(String input) {
        return textOf(ChatRenderUtils.parseTextWithColoursAndIcons(
                input, metrics, null, true, Color.WHITE, FontSize.REGULAR, null));
    }

    private static String renderName(String input) {
        return textOf(ChatRenderUtils.parseTextWithIcons(
                input, metrics, null, Color.WHITE, FontSize.REGULAR));
    }

    /** The reported bug: "Gzzz@@@" arrives escaped as "Gzzz<at><at><at>" and rendered literally. */
    @Test
    public void bodyDecodesAtEscape() {
        assertEquals("Gzzz@@@", renderBody("Gzzz<at><at><at>"));
    }

    /** The <at> decode must not regress the existing <lt> / <gt> decoding in the same parser. */
    @Test
    public void bodyDecodesAtAlongsideLtGt() {
        assertEquals("a@<b>@", renderBody("a<at><lt>b<gt><at>"));
    }

    /** Sender names go through parseTextWithIcons, which also escapes literal @. */
    @Test
    public void nameDecodesAtEscape() {
        assertEquals("Bob@Home", renderName("Bob<at>Home"));
    }

    /** Plain text with no escapes is unchanged. */
    @Test
    public void plainTextUnchanged() {
        assertEquals("hello world", renderBody("hello world"));
    }
}

package com.chatwidgets.overlay;

import com.chatwidgets.model.FontSize;
import org.junit.BeforeClass;
import org.junit.Test;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Covers in-game chat formatting tags and {@code <str_NAME=VALUE>} template variables in
 * {@link ChatRenderUtils#parseTextWithColoursAndIcons}. Expected behaviour mirrors the game's font
 * renderer ({@code AbstractFont.decodeTag}) and the client's template expansion.
 */
public class ChatFormattingTagsTest {

    private static FontMetrics metrics;

    @BeforeClass
    public static void setUp() {
        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        metrics = g.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        g.dispose();
    }

    private static List<TextSegment> parse(String input) {
        return ChatRenderUtils.parseTextWithColoursAndIcons(
                input, metrics, null, true, Color.WHITE, FontSize.REGULAR, null);
    }

    /** Returns the single text segment whose text is exactly {@code text}. */
    private static TextSegment segment(List<TextSegment> segments, String text) {
        TextSegment found = null;
        for (TextSegment s : segments) {
            if (s.iconId == -1 && s.text.equals(text)) {
                assertNull("more than one segment reads '" + text + "'", found);
                found = s;
            }
        }
        if (found == null) {
            throw new AssertionError("no segment reads '" + text + "' in " + textOf(segments));
        }
        return found;
    }

    /** Concatenates segment text, writing each line break as a newline. */
    private static String textOf(List<TextSegment> segments) {
        StringBuilder sb = new StringBuilder();
        for (TextSegment s : segments) {
            if (s.iconId == TextSegment.LINE_BREAK) {
                sb.append('\n');
            } else if (s.iconId == -1) {
                sb.append(s.text);
            }
        }
        return sb.toString();
    }

    @Test
    public void expandsQuestTemplateVariable() {
        assertEquals("Username has completed a quest: Crab Quest",
                textOf(parse("<str_quest_name_0=Crab Quest>Username has completed a quest: <str_quest_name_0>")));
    }

    /** The PvP Performance Tracker notice: every tag is hidden, only the text remains. */
    @Test
    public void hidesAllTagsInPluginUpdateNotice() {
        assertEquals("PvP Performance Tracker v1.9.0 Update: Added Pete Kayer fight tracking.",
                textOf(parse("<html><shad=000000><col=ee4500>PvP Performance Tracker</col> "
                        + "<col=fa1500><u>v1.9.0</u></col> <col=ee4500>Update:</col></shad> "
                        + "<col=842b00>Added Pete Kayer fight tracking.")));
    }

    @Test
    public void underlineUsesTagColourOrBlackWhenBare() {
        List<TextSegment> segs = parse("a<u>b</u>c<u=ff0000>d</u>");
        assertNull(segment(segs, "a").underlineColor);
        assertEquals(Color.BLACK, segment(segs, "b").underlineColor);
        assertNull(segment(segs, "c").underlineColor);
        assertEquals(new Color(0xff0000), segment(segs, "d").underlineColor);
    }

    @Test
    public void strikethroughUsesTagColourOrDarkRedWhenBare() {
        List<TextSegment> segs = parse("a<str>b</str>c<str=00ff00>d</str>");
        assertNull(segment(segs, "a").strikeColor);
        assertEquals(new Color(0x800000), segment(segs, "b").strikeColor);
        assertNull(segment(segs, "c").strikeColor);
        assertEquals(new Color(0x00ff00), segment(segs, "d").strikeColor);
    }

    /** A null shadow colour means "the base shadow", which the renderer resolves from config. */
    @Test
    public void shadowUsesTagColourOrBlackWhenBareAndEndRestoresBase() {
        List<TextSegment> segs = parse("a<shad>b</shad>c<shad=0000ff>d</shad>e");
        assertNull(segment(segs, "a").shadowColor);
        assertEquals(Color.BLACK, segment(segs, "b").shadowColor);
        assertNull(segment(segs, "c").shadowColor);
        assertEquals(new Color(0x0000ff), segment(segs, "d").shadowColor);
        assertNull(segment(segs, "e").shadowColor);
    }

    /** Formatting stacks independently: colour, underline and shadow all apply to the same text. */
    @Test
    public void formattingCombines() {
        TextSegment v = segment(parse("<shad=000000><col=fa1500><u>v1.9.0</u></col></shad> x"), "v1.9.0");
        assertEquals(new Color(0xfa1500), v.color);
        assertEquals(Color.BLACK, v.underlineColor);
        assertEquals(Color.BLACK, v.shadowColor);
    }

    /** <br> ends the line and resets colour, strikethrough, underline and shadow to base. */
    @Test
    public void lineBreakResetsAllFormatting() {
        List<TextSegment> segs = parse("<col=ff0000><str><u><shad=00ff00>a<br>b");
        assertEquals("a\nb", textOf(segs));
        TextSegment b = segment(segs, "b");
        assertEquals(Color.WHITE, b.color);
        assertNull(b.strikeColor);
        assertNull(b.underlineColor);
        assertNull(b.shadowColor);
    }

    /** The game font breaks the line at <n> just like <br>. */
    @Test
    public void newlineTagBreaksLineAndResetsFormatting() {
        List<TextSegment> segs = parse("<u>a<n>b");
        assertEquals("a\nb", textOf(segs));
        assertNull(segment(segs, "b").underlineColor);
    }

    @Test
    public void nonBreakingHyphenRendersAsHyphen() {
        assertEquals("Ice-cold", textOf(parse("Ice<nbh>cold")));
    }

    /**
     * Bare tags are exact matches: an undefined template reference or a look-alike tag must not
     * switch on strikethrough or underline, and is hidden like any unknown tag.
     */
    @Test
    public void lookAlikeTagsAreHiddenAndDoNotFormat() {
        List<TextSegment> segs = parse("a<str_region_0>b<strike>c<u2>d<shadow>e");
        assertEquals("abcde", textOf(segs));
        for (TextSegment s : segs) {
            assertNull(s.strikeColor);
            assertNull(s.underlineColor);
            assertNull(s.shadowColor);
        }
    }

    /** A tag with bad hex is ignored: the previous formatting stays in effect. */
    @Test
    public void badHexTagIsIgnored() {
        List<TextSegment> segs = parse("<col=ff0000>a<col=zz>b<u=zz>c");
        assertEquals("abc", textOf(segs));
        assertEquals(new Color(0xff0000), segment(segs, "abc").color);
        assertNull(segment(segs, "abc").underlineColor);
    }

    /** A '<' with no closing '>' is not a tag, so it stays visible. */
    @Test
    public void unterminatedTagStaysLiteral() {
        assertEquals("a <3 b", textOf(parse("a <3 b")));
    }

    @Test
    public void invalidIconIdsCannotBecomeInternalSentinels() {
        List<TextSegment> segs = parse("a<img=-2>b<img=-1>c<img=2147483648>d<img=x>e");
        assertEquals("abcde", textOf(segs));
        assertEquals(1, ChatRenderUtils.wrapSegments(segs, metrics, 500, 500, Color.WHITE).size());
    }

    /** Wrapping splits text into words and spaces; each piece keeps the source's formatting. */
    @Test
    public void wrappingKeepsFormatting() {
        List<TextSegment> segs = parse("<str><u=ff0000><shad=00ff00>one two three");
        int narrow = metrics.stringWidth("one two");
        List<List<TextSegment>> lines = ChatRenderUtils.wrapSegments(segs, metrics, narrow, narrow, Color.WHITE);
        assertEquals(2, lines.size());
        for (List<TextSegment> line : lines) {
            for (TextSegment s : line) {
                assertEquals(new Color(0x800000), s.strikeColor);
                assertEquals(new Color(0xff0000), s.underlineColor);
                assertEquals(new Color(0x00ff00), s.shadowColor);
            }
        }
    }

    /** Without contextual colours, <col> is ignored but decorations keep their tag colours. */
    @Test
    public void decorationsApplyWithoutContextualColours() {
        List<TextSegment> segs = ChatRenderUtils.parseTextWithColoursAndIcons(
                "<col=ff0000><u=00ff00>a", metrics, null, false, Color.WHITE, FontSize.REGULAR, null);
        TextSegment a = segment(segs, "a");
        assertEquals(Color.WHITE, a.color);
        assertEquals(new Color(0x00ff00), a.underlineColor);
    }
}

package com.chatwidgets.overlay;

import com.chatwidgets.model.FontSize;
import com.chatwidgets.model.MessageVariant;
import com.chatwidgets.model.WidgetMessage;
import net.runelite.api.ChatMessageType;
import org.junit.BeforeClass;
import org.junit.Test;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

import static org.junit.Assert.assertEquals;

/**
 * Covers the non-sender headers {@link ChatRenderUtils#buildMessageLines} adds for {@code |}-parsed
 * messages: the always-on {@code Broadcast:} label and the {@code [clan tag]} on clan notifications,
 * gated by Show Channel Names. Needs only a headless {@link FontMetrics}.
 */
public class MessageHeaderTest {

    private static FontMetrics metrics;

    @BeforeClass
    public static void setUp() {
        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        metrics = g.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        g.dispose();
    }

    /** Renders one unwrapped line and concatenates its non-icon segment text. */
    private static String render(WidgetMessage msg, boolean showChannelName) {
        List<RenderLine> lines = ChatRenderUtils.buildMessageLines(msg, metrics, 1000, 0L, 0L, false,
                Color.WHITE, true, true, FontSize.REGULAR, null, false, null, showChannelName, null);
        assertEquals(1, lines.size());
        StringBuilder sb = new StringBuilder();
        for (TextSegment s : lines.get(0).segments) {
            if (s.iconId == -1) {
                sb.append(s.text);
            }
        }
        return sb.toString();
    }

    private static WidgetMessage clanNotification(ChatMessageType type, MessageVariant variant, String tag) {
        return WidgetMessage.gameMessage("Bob completed a task.", 0L, type, false, variant, null, null, tag);
    }

    @Test
    public void clanNotificationTaggedWhenChannelNamesShown() {
        WidgetMessage msg = clanNotification(ChatMessageType.CLAN_MESSAGE, MessageVariant.NORMAL, "My Clan");
        assertEquals("[My Clan] Bob completed a task.", render(msg, true));
    }

    @Test
    public void clanNotificationUntaggedWhenChannelNamesHidden() {
        WidgetMessage msg = clanNotification(ChatMessageType.CLAN_MESSAGE, MessageVariant.NORMAL, "My Clan");
        assertEquals("Bob completed a task.", render(msg, false));
    }

    @Test
    public void gimNotificationTaggedWithGroupName() {
        WidgetMessage msg = clanNotification(ChatMessageType.CLAN_GIM_MESSAGE, MessageVariant.GIM, "Iron Pals");
        assertEquals("[Iron Pals] Bob completed a task.", render(msg, true));
    }

    @Test
    public void clanNotificationWithoutTagHasNoBrackets() {
        WidgetMessage msg = clanNotification(ChatMessageType.CLAN_MESSAGE, MessageVariant.NORMAL, null);
        assertEquals("Bob completed a task.", render(msg, true));
    }

    @Test
    public void broadcastLabelShownRegardlessOfChannelNames() {
        WidgetMessage msg = WidgetMessage.gameMessage("<img=12> Test news", 0L, ChatMessageType.BROADCAST,
                false, MessageVariant.NORMAL, null, "https://example.com", null);
        // The <img=12> icon segment is skipped by render(); its trailing space is body text.
        assertEquals("Broadcast:  Test news", render(msg, false));
        assertEquals("Broadcast:  Test news", render(msg, true));
    }

    @Test
    public void plainGameMessageHasNoHeader() {
        WidgetMessage msg = WidgetMessage.gameMessage("Hello.", 0L, ChatMessageType.GAMEMESSAGE, false);
        assertEquals("Hello.", render(msg, true));
    }
}
